/**
 * Tests for {@link BMPImageReader#read(int, ImageReadParam)}.
 * <p>
 * All BMP files used in this test are synthesized in-memory, byte by byte, so that the
 * exact pixel values, paddings, palettes and compressions are known and can be asserted.
 */
public class BMPImageReaderReadTests {

    private static final int BLACK = 0x000000;
    private static final int RED = 0xFF0000;
    private static final int GREEN = 0x00FF00;
    private static final int BLUE = 0x0000FF;
    private static final int WHITE = 0xFFFFFF;
    private static final int GREY = 0x808080;

    private static final int[] PALETTE_16 = {
            BLACK, RED, GREEN, BLUE, WHITE,
            GREY, 0x404040, 0xC0C0C0, 0x800000, 0x008000,
            0x000080, 0x808000, 0x008080, 0x800080, 0xFFFF80, 0x80FFFF
    };

    private BMPImageReader reader;
    private final List<String> warnings = new ArrayList<>();

    @BeforeEach
    void setUp() {
        reader = new BMPImageReader();
        warnings.clear();
        reader.addIIOReadWarningListener((source, warning) -> warnings.add(warning));
    }

    // ---------------------------------------------------------------------
    // Normal cases: uncompressed, all supported pixel depths
    // ---------------------------------------------------------------------

    @Test
    public void testRead24BitBottomUp() throws IOException {
        BufferedImage image = read(bmp(2, 2, 24, DIB.COMPRESSION_RGB, 0, null, pixels(2, 24,
                new int[]{RED, WHITE},     // top row, stored last
                new int[]{BLUE, GREEN}),   // bottom row, stored first
                null, false));

        assertNotNull(image);
        assertEquals(2, image.getWidth());
        assertEquals(2, image.getHeight());
        assertEquals(BufferedImage.TYPE_3BYTE_BGR, image.getType());
        assertEquals(3, image.getRaster().getNumBands());

        assertEquals(argb(RED), image.getRGB(0, 0));
        assertEquals(argb(WHITE), image.getRGB(1, 0));
        assertEquals(argb(BLUE), image.getRGB(0, 1));
        assertEquals(argb(GREEN), image.getRGB(1, 1));
        assertTrue(warnings.isEmpty(), "No warnings expected, was: " + warnings);
    }

    @Test
    public void testRead24BitTopDown() throws IOException {
        BufferedImage image = read(bmp(2, 2, 24, DIB.COMPRESSION_RGB, 0, null, pixelsTopDown(2, 24,
                new int[]{RED, GREEN},     // top row, stored first because of top-down flag
                new int[]{BLUE, WHITE}),   // bottom row
                null, true));

        assertEquals(2, image.getWidth());
        assertEquals(2, image.getHeight());
        assertEquals(argb(RED), image.getRGB(0, 0));
        assertEquals(argb(GREEN), image.getRGB(1, 0));
        assertEquals(argb(BLUE), image.getRGB(0, 1));
        assertEquals(argb(WHITE), image.getRGB(1, 1));
    }

    @Test
    public void testRead24BitSinglePixelSkipsRowPadding() throws IOException {
        // 1 pixel 24 bit => 3 bytes of data padded to a full 4 byte row
        BufferedImage image = read(bmp(1, 1, 24, DIB.COMPRESSION_RGB, 0, null, pixels(1, 24,
                new int[]{BLUE}), null, false));

        assertEquals(1, image.getWidth());
        assertEquals(1, image.getHeight());
        assertEquals(argb(BLUE), image.getRGB(0, 0));
    }

    @Test
    public void testRead8BitIndexed() throws IOException {
        int[] palette = {BLACK, RED, GREEN, BLUE};
        BufferedImage image = read(bmp(4, 2, 8, DIB.COMPRESSION_RGB, palette.length, palette, pixels(4, 8,
                new int[]{3, 2, 1, 0},   // top row
                new int[]{1, 2, 3, 0}),  // bottom row
                null, false));

        assertEquals(4, image.getWidth());
        assertEquals(2, image.getHeight());

        IndexColorModel colorModel = assertInstanceOf(IndexColorModel.class, image.getColorModel());
        assertEquals(4, colorModel.getMapSize());
        assertEquals(8, colorModel.getPixelSize());
        assertEquals(argb(RED), colorModel.getRGB(1));

        assertEquals(argb(BLUE), image.getRGB(0, 0));
        assertEquals(argb(GREEN), image.getRGB(1, 0));
        assertEquals(argb(RED), image.getRGB(2, 0));
        assertEquals(argb(BLACK), image.getRGB(3, 0));

        assertEquals(argb(RED), image.getRGB(0, 1));
        assertEquals(argb(GREEN), image.getRGB(1, 1));
        assertEquals(argb(BLUE), image.getRGB(2, 1));
        assertEquals(argb(BLACK), image.getRGB(3, 1));
    }

    @Test
    public void testRead8BitSinglePixelSkipsRowPadding() throws IOException {
        int[] palette = {WHITE, BLACK};
        BufferedImage image = read(bmp(1, 1, 8, DIB.COMPRESSION_RGB, palette.length, palette, pixels(1, 8,
                new int[]{1}), null, false));

        assertEquals(argb(BLACK), image.getRGB(0, 0));
    }

    @Test
    public void testRead4BitPacked() throws IOException {
        BufferedImage image = read(bmp(3, 2, 4, DIB.COMPRESSION_RGB, PALETTE_16.length, PALETTE_16, pixels(3, 4,
                new int[]{3, 4, 5},       // top row
                new int[]{0, 1, 2}),      // bottom row
                null, false));

        assertEquals(3, image.getWidth());
        assertEquals(2, image.getHeight());

        IndexColorModel colorModel = assertInstanceOf(IndexColorModel.class, image.getColorModel());
        assertEquals(16, colorModel.getMapSize());
        assertEquals(4, colorModel.getPixelSize());

        assertEquals(argb(BLUE), image.getRGB(0, 0));
        assertEquals(argb(WHITE), image.getRGB(1, 0));
        assertEquals(argb(GREY), image.getRGB(2, 0));

        assertEquals(argb(BLACK), image.getRGB(0, 1));
        assertEquals(argb(RED), image.getRGB(1, 1));
        assertEquals(argb(GREEN), image.getRGB(2, 1));
    }

    @Test
    public void testRead2BitPacked() throws IOException {
        int[] palette = {BLACK, RED, GREEN, BLUE};
        BufferedImage image = read(bmp(4, 1, 2, DIB.COMPRESSION_RGB, palette.length, palette, pixels(4, 2,
                new int[]{0, 1, 2, 3}), null, false));

        assertEquals(4, image.getWidth());
        assertEquals(argb(BLACK), image.getRGB(0, 0));
        assertEquals(argb(RED), image.getRGB(1, 0));
        assertEquals(argb(GREEN), image.getRGB(2, 0));
        assertEquals(argb(BLUE), image.getRGB(3, 0));
    }

    @Test
    public void testRead1BitPacked() throws IOException {
        int[] palette = {BLACK, WHITE};
        BufferedImage image = read(bmp(3, 2, 1, DIB.COMPRESSION_RGB, palette.length, palette, pixels(3, 1,
                new int[]{0, 1, 0},      // top row
                new int[]{1, 0, 1}),     // bottom row
                null, false));

        assertEquals(argb(BLACK), image.getRGB(0, 0));
        assertEquals(argb(WHITE), image.getRGB(1, 0));
        assertEquals(argb(BLACK), image.getRGB(2, 0));

        assertEquals(argb(WHITE), image.getRGB(0, 1));
        assertEquals(argb(BLACK), image.getRGB(1, 1));
        assertEquals(argb(WHITE), image.getRGB(2, 1));
    }

    @Test
    public void testRead16BitNoMasksDefaultsTo555() throws IOException {
        BufferedImage image = read(bmp(2, 1, 16, DIB.COMPRESSION_RGB, 0, null, pixels(2, 16,
                new int[]{0xF800, 0x001F}), null, false));

        assertEquals(BufferedImage.TYPE_USHORT_555_RGB, image.getType());
        assertEquals(argb(RED), image.getRGB(0, 0));
        assertEquals(argb(BLUE), image.getRGB(1, 0));
    }

    @Test
    public void testRead16BitBitFields565() throws IOException {
        BufferedImage image = read(bmp(3, 1, 16, DIB.COMPRESSION_BITFIELDS, 0, null, pixels(3, 16,
                new int[]{0xF800, 0x07E0, 0x001F}),
                new int[]{0xF800, 0x07E0, 0x001F}, false));

        assertEquals(3, image.getWidth());
        assertEquals(argb(RED), image.getRGB(0, 0));
        assertEquals(argb(GREEN), image.getRGB(1, 0));
        assertEquals(argb(BLUE), image.getRGB(2, 0));
    }

    @Test
    public void testRead32BitRGB() throws IOException {
        BufferedImage image = read(bmp(2, 1, 32, DIB.COMPRESSION_RGB, 0, null, pixels(2, 32,
                new int[]{0xFF0000FF, 0xFFFF0000}), null, false));

        assertEquals(BufferedImage.TYPE_INT_RGB, image.getType());
        assertEquals(argb(BLUE), image.getRGB(0, 0));
        assertEquals(argb(RED), image.getRGB(1, 0));
    }

    @Test
    public void testRead32BitAlphaBitFields() throws IOException {
        BufferedImage image = read(bmp(2, 1, 32, DIB.COMPRESSION_ALPHA_BITFIELDS, 0, null, pixels(2, 32,
                new int[]{0xFF0000FF, 0xFFFF0000}),
                new int[]{0x00FF0000, 0x0000FF00, 0x000000FF, 0xFF000000}, false));

        assertEquals(argb(BLUE), image.getRGB(0, 0));
        assertEquals(argb(RED), image.getRGB(1, 0));
    }

    // ---------------------------------------------------------------------
    // RLE compressed images
    // ---------------------------------------------------------------------

    @Test
    public void testReadRLE8() throws IOException {
        int[] palette = {BLACK, RED, GREEN, BLUE};
        byte[] rle = {
                2, 1, 2, 2,  // bottom row: indices 1,1,2,2
                2, 3, 2, 0,  // top row: indices 3,3,0,0
                0, 1         // end of bitmap
        };

        BufferedImage image = read(bmp(4, 2, 8, DIB.COMPRESSION_RLE8, palette.length, palette, rle, null, false));

        assertEquals(4, image.getWidth());
        assertEquals(2, image.getHeight());

        assertEquals(argb(BLUE), image.getRGB(0, 0));
        assertEquals(argb(BLUE), image.getRGB(1, 0));
        assertEquals(argb(BLACK), image.getRGB(2, 0));
        assertEquals(argb(BLACK), image.getRGB(3, 0));

        assertEquals(argb(RED), image.getRGB(0, 1));
        assertEquals(argb(RED), image.getRGB(1, 1));
        assertEquals(argb(GREEN), image.getRGB(2, 1));
        assertEquals(argb(GREEN), image.getRGB(3, 1));
    }

