    @Test
    public void testReadAbortedBeforeReadOnlyReadsFirstRow() throws IOException {
        byte[] file = bmp(2, 4, 24, DIB.COMPRESSION_RGB, 0, null, pixels(2, 24,
                new int[]{RED, RED},         // rows given top first...
                new int[]{GREEN, GREEN},
                new int[]{BLUE, BLUE},
                new int[]{WHITE, WHITE}), null, false);

        final int[] aborts = {0};
        reader.addIIOReadProgressListener(new ProgressListenerBase() {
            @Override
            public void readAborted(ImageReader source) {
                aborts[0]++;
            }
        });

        reader.setInput(imageInputStream(file));
        reader.abort();

        BufferedImage image = reader.read(0, null);

        assertEquals(1, aborts[0], "Expected exactly one abort event");
        assertEquals(4, image.getHeight());

        // Only the first (bottom) row was decoded before the loop broke, the rest is untouched
        assertEquals(argb(WHITE), image.getRGB(0, 3));
        assertEquals(argb(WHITE), image.getRGB(1, 3));
        assertEquals(0, image.getRGB(0, 0));
        assertEquals(0, image.getRGB(0, 2));
    }

    @Test
    public void testReadAbortedByProgressListener() throws IOException {
        byte[] file = bmp(2, 4, 24, DIB.COMPRESSION_RGB, 0, null, pixels(2, 24,
                new int[]{RED, RED},
                new int[]{GREEN, GREEN},
                new int[]{BLUE, BLUE},
                new int[]{WHITE, WHITE}), null, false);

        final int[] progress = {0};
        final int[] aborts = {0};

        reader.addIIOReadProgressListener(new ProgressListenerBase() {
            @Override
            public void imageProgress(ImageReader source, float percentageDone) {
                progress[0]++;
                source.abort();
            }

            @Override
            public void readAborted(ImageReader source) {
                aborts[0]++;
            }
        });

        BufferedImage image = read(file);

        assertEquals(1, progress[0], "Expected exactly one progress event before aborting");
        assertEquals(1, aborts[0], "Expected exactly one abort event");
        assertEquals(4, image.getHeight());
        assertEquals(0, image.getRGB(0, 0));
    }

    @Test
    public void testReadTwiceYieldsSamePixels() throws IOException {
        byte[] file = pattern24Bit(3, 3);

        reader.setInput(imageInputStream(file));

        BufferedImage first = reader.read(0, null);
        BufferedImage second = reader.read(0, null);

        assertNotNull(first);
        assertNotNull(second);

        for (int y = 0; y < 3; y++) {
            for (int x = 0; x < 3; x++) {
                assertEquals(argb(pattern(x, y)), first.getRGB(x, y));
                assertEquals(first.getRGB(x, y), second.getRGB(x, y));
            }
        }
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private BufferedImage read(byte[] file) throws IOException {
        return read(file, null);
    }

    private BufferedImage read(byte[] file, ImageReadParam param) throws IOException {
        reader.setInput(imageInputStream(file));
        return reader.read(0, param);
    }

    private static ImageInputStream imageInputStream(byte[] file) {
        return new ByteArrayImageInputStream(file);
    }

    private static int argb(int rgb) {
        return 0xFF000000 | rgb;
    }

    /** Pixel pattern used by the region/subsampling tests. Unique per x/y coordinate. */
    private static int pattern(int x, int y) {
        return (x * 16 + 1) << 16 | (y * 16 + 1) << 8 | 0x40;
    }

    private static byte[] pattern24Bit(int width, int height) {
        int[][] rows = new int[height][width];
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                rows[y][x] = pattern(x, y);
            }
        }

        return bmp(width, height, 24, DIB.COMPRESSION_RGB, 0, null, pixels(width, 24, rows), null, false);
    }

    private static int rowSize(int width, int bitCount) {
        return ((bitCount * width + 31) / 32) * 4;
    }

    /** Builds the raw pixel data as stored in the file, rows in top-first order are reversed (bottom-up). */
    private static byte[] pixels(int width, int bitCount, int[]... rowsTopFirst) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (int i = rowsTopFirst.length - 1; i >= 0; i--) {
            byte[] row = row(width, bitCount, rowsTopFirst[i]);
            out.write(row, 0, row.length);
        }

        return out.toByteArray();
    }

    /** Builds the raw pixel data for a top-down bitmap: rows are stored in image order. */
    private static byte[] pixelsTopDown(int width, int bitCount, int[]... rowsTopFirst) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (int[] samples : rowsTopFirst) {
            byte[] row = row(width, bitCount, samples);
            out.write(row, 0, row.length);
        }

        return out.toByteArray();
    }

    /**
     * Encodes one padded scan line.
     * <p>
     * For 24 bit the samples are {@code 0xRRGGBB} values, for 32/16 bit they are the raw
     * little endian words, for 8/4/2/1 bit they are palette indices.
     * </p>
     */
    private static byte[] row(int width, int bitCount, int[] samples) {
        if (samples.length != width) {
            throw new IllegalArgumentException("Expected " + width + " samples, got " + samples.length);
        }

        byte[] row = new byte[rowSize(width, bitCount)];

        switch (bitCount) {
            case 1:
            case 2:
            case 4: {
                int perByte = 8 / bitCount;
                int mask = (1 << bitCount) - 1;
                for (int x = 0; x < width; x++) {
                    int shift = 8 - bitCount - (x % perByte) * bitCount;
                    row[x / perByte] |= (byte) ((samples[x] & mask) << shift);
                }
                break;
            }
            case 8:
                for (int x = 0; x < width; x++) {
                    row[x] = (byte) samples[x];
                }
                break;
            case 16:
                for (int x = 0; x < width; x++) {
                    row[x * 2] = (byte) samples[x];
                    row[x * 2 + 1] = (byte) (samples[x] >>> 8);
