@Test
public void testReadRLE4() throws IOException {
    // Each RLE4 row is decoded into a scan line padded to 4 bytes, ie. 8 nibbles for a width of 4,
    // hence the trailing zero padding nibbles in the absolute mode runs below.
    byte[] rle = {
            0, 8, 0x12, 0x12, 0x00, 0x00, // bottom row: nibbles 1,2,1,2 + padding
            0, 8, 0x30, 0x30, 0x00, 0x00, // top row: nibbles 3,0,3,0 + padding
            0, 1                          // end of bitmap
    };

    BufferedImage image = read(bmp(4, 2, 4, DIB.COMPRESSION_RLE4, PALETTE_16.length, PALETTE_16, rle, null, false));

    assertEquals(4, image.getWidth());
    assertEquals(2, image.getHeight());

    assertEquals(argb(BLUE), image.getRGB(0, 0));
    assertEquals(argb(BLACK), image.getRGB(1, 0));
    assertEquals(argb(BLUE), image.getRGB(2, 0));
    assertEquals(argb(BLACK), image.getRGB(3, 0));

    assertEquals(argb(RED), image.getRGB(0, 1));
    assertEquals(argb(GREEN), image.getRGB(1, 1));
    assertEquals(argb(RED), image.getRGB(2, 1));
    assertEquals(argb(GREEN), image.getRGB(3, 1));
}

