@Test
public void testWarningWhenColorMapIsLargerThanRaster() throws IOException {
    int[] palette = {BLACK, RED, GREEN, BLUE};

    // Declares 256 colors, but only 4 palette entries are physically present before the pixel data
    BufferedImage image = read(bmp(2, 1, 8, DIB.COMPRESSION_RGB, 256, palette, pixels(2, 8,
            new int[]{1, 3}), null, false));

    assertEquals(argb(RED), image.getRGB(0, 0));
    assertEquals(argb(BLUE), image.getRGB(1, 0));

    assertEquals(Arrays.asList(
            "Color map contains more colors than raster allows (256). Ignoring entries above 4."), warnings);
}

