            if (markerIndex != 0) {
                markerIndex = 0;
                return (0xFF00 | marker) << 8;
            }

            temp[0] <<= 8;
            input = this.input.readUnsignedByte();

            if (input == 0xFF) {
                marker = this.input.readUnsignedByte();
                if (marker != 0) {
                    markerIndex = 9;
                }
            }

            temp[0] |= input;
            index[0] += 8;
        }

        if (index[0] < 0) {
            throw new IOException("index=" + index[0] + " in getn()");
        }

        if (index[0] < markerIndex) {
            markerIndex = 0;
            return (0xFF00 | marker) << 8;
        }

        result = temp[0] >> index[0];
        temp[0] &= (mask >> (16 - index[0]));
    }

