        // Predictor 1 (Ra) means: first sample = 128, then every sample is the previous one plus 1.
        // Row 1: 128+1=129, 129+1=130. Row 2: 129+1=130 (above), 130+1=131.
        byte[] jpeg = new JpegStream()
                .soi()
                .segment(JPEG.DHT, dht(0, 0, ONE_CODE_OF_LENGTH_1, new int[]{1}))
                .segment(JPEG.SOF3, sof(8, 2, 2, new int[][]{{1, 1, 1, 0}}))
                .segment(JPEG.SOS, sos(new int[][]{{1, 0, 0}}, 1, 0, 0, 0))
                .bytes(0x55, 0x55, 0x55, 0x55, 0x55, 0x55, 0x55, 0x55)
                .eoi()
                .toByteArray();

        int[][] result = decode(jpeg);

        assertEquals(1, result.length);
        assertArrayEquals(new int[]{129, 130, 130, 131}, result[0]);
    }

    @Test
    void decodeGrayWithNegativeDifferences() throws IOException {
