        // Row 1: 128-1=127, 127-1=126. Row 2: 127-1=126 (above), 126-1=125.
        // The bits '00' repeated is 0x00, but 0x00 also contains the value 0 for the next code,
        // therefore the '0' sign bits are made explicit by using 0x10 (bits 0001 0000) ...
        // Simpler: use a stream of '00' bit pairs, i.e. all zero bytes.
        byte[] jpeg = new JpegStream()
                .soi()
                .segment(JPEG.DHT, dht(0, 0, ONE_CODE_OF_LENGTH_1, new int[]{1}))
                .segment(JPEG.SOF3, sof(8, 2, 2, new int[][]{{1, 1, 1, 0}}))
                .segment(JPEG.SOS, sos(new int[][]{{1, 0, 0}}, 1, 0, 0, 0))
                .bytes(ZERO_BITS)
                .eoi()
                .toByteArray();

        int[][] result = decode(jpeg);

        assertEquals(1, result.length);
        assertArrayEquals(new int[]{127, 126, 126, 125}, result[0]);
    }

