package com.twelvemonkeys.imageio.plugins.jpeg;

import com.twelvemonkeys.imageio.metadata.jpeg.JPEG;
import org.junit.jupiter.api.Test;

import javax.imageio.IIOException;
import javax.imageio.ImageReader;
