                .soi()
                .segment(JPEG.DHT, dht(0, 0, ONE_CODE_OF_LENGTH_1, new int[]{0}))
                .segment(JPEG.SOF3, sof(8, 2, 2, new int[][]{{1, 1, 1, 0}, {2, 1, 1, 0}}))
                .segment(JPEG.SOS, sos(new int[][]{{1, 0, 0}, {2, 0, 0}}, 1, 0, 0, 0))
