    @Test
    void decodeSkipsSegmentsBeforeStartOfScan() throws IOException {
        // Any segment (not SOS) before the scan must be skipped, using its length
        byte[] jpeg = new JpegStream()
                .soi()
                .segment(JPEG.COM, "A comment that must be skipped".getBytes("UTF-8"))
                .segment(JPEG.DHT, dht(0, 0, ONE_CODE_OF_LENGTH_1, new int[]{0}))
