    @Test
    void decodeWithRestartInterval() throws IOException {
        // 4x1 image with a restart interval of 2. The prediction is reset to 2^(8-0-1) = 128 at the
        // start of each restart interval, so both intervals decode to 128+1 = 129, 129+1 = 130.
        byte[] jpeg = new JpegStream()
                .soi()
                .segment(JPEG.DHT, dht(0, 0, ONE_CODE_OF_LENGTH_7, new int[]{1}))
                .segment(JPEG.DRI, new byte[]{0x00, 0x02})
                .segment(JPEG.SOF3, sof(8, 4, 1, new int[][]{{1, 1, 1, 0}}))
                .segment(JPEG.SOS, sos(new int[][]{{1, 0, 0}}, 1, 0, 0, 0))
                .bytes(0x01, 0x01)
                .bytes(0xFF, 0xD0) // RST0
                .bytes(0x01, 0x01)
                .eoi()
                .toByteArray();

        int[][] result = decode(jpeg);

        assertEquals(1, result.length);
        assertArrayEquals(new int[]{129, 130, 129, 130}, result[0]);
    }

    @Test
    void decodeWithPredictorSelectionThree() throws IOException {
        // Predictor selection 3 (C, the sample above-left): every sample is predicted from the
        // diagonal neighbour, which for the first row/column falls back to the above/left sample.
        // Diffs of +1: 128+1=129, then 129+1=130, 129+1=130 and 129+1=130
        byte[] jpeg = new JpegStream()
                .soi()
                .segment(JPEG.DHT, dht(0, 0, ONE_CODE_OF_LENGTH_7, new int[]{1}))
                .segment(JPEG.SOF3, sof(8, 2, 2, new int[][]{{1, 1, 1, 0}}))
                .segment(JPEG.SOS, sos(new int[][]{{1, 0, 0}}, 3, 0, 0, 0))
                .bytes(EIGHT_TIMES_PLUS_ONE)
                .eoi()
                .toByteArray();

        int[][] result = decode(jpeg);

        assertEquals(1, result.length);
        assertArrayEquals(new int[]{129, 130, 130, 130}, result[0]);
    }

    @Test
    void decodeWithPredictorSelectionFour() throws IOException {
        // Predictor selection 4 (A + B - C): first sample 128+1 = 129, then 129+1 = 130,
        // 129+1 = 130 and finally 130 + 130 - 129 + 1 = 132
        byte[] jpeg = new JpegStream()
                .soi()
                .segment(JPEG.DHT, dht(0, 0, ONE_CODE_OF_LENGTH_7, new int[]{1}))
                .segment(JPEG.SOF3, sof(8, 2, 2, new int[][]{{1, 1, 1, 0}}))
                .segment(JPEG.SOS, sos(new int[][]{{1, 0, 0}}, 4, 0, 0, 0))
                .bytes(EIGHT_TIMES_PLUS_ONE)
                .eoi()
                .toByteArray();

        int[][] result = decode(jpeg);

        assertEquals(1, result.length);
        assertArrayEquals(new int[]{129, 130, 130, 132}, result[0]);
    }

    @Test
    void decodeOutputsPredictionWhenEoiIsHitForLastPixel() throws IOException {
        // The entropy coded data ends (EOI is encountered) while decoding the last sample of the
        // image. The predicted value for that sample is still output.
        // 2x2 with diffs of +1: 129, 130, 130, and the last sample is predicted from its left
        // neighbour: 130.
        byte[] jpeg = new JpegStream()
                .soi()
                .segment(JPEG.DHT, dht(0, 0, ONE_CODE_OF_LENGTH_7, new int[]{1}))
                .segment(JPEG.SOF3, sof(8, 2, 2, new int[][]{{1, 1, 1, 0}}))
                .segment(JPEG.SOS, sos(new int[][]{{1, 0, 0}}, 1, 0, 0, 0))
                .bytes(0x01, 0x01, 0x01)
                .eoi()
                .toByteArray();

        int[][] result = decode(jpeg);

        assertEquals(1, result.length);
        assertArrayEquals(new int[]{129, 130, 130, 130}, result[0]);
    }

    @Test
    void decodeUsesAcTableForDcWhenDcTableIsMissing() throws IOException {
        // Lossless JPEG with only an AC (class 1) Huffman table: the AC table is used for the
        // differences, and a warning is reported to the listener delegate.
        List<String> warnings = new ArrayList<>();
        JPEGImageReader delegate = warningCollectingReader(warnings);

        byte[] jpeg = new JpegStream()
                .soi()
                .segment(JPEG.DHT, dht(1, 0, ONE_CODE_OF_LENGTH_7, new int[]{1}))
                .segment(JPEG.SOF3, sof(8, 2, 2, new int[][]{{1, 1, 1, 0}}))
                .segment(JPEG.SOS, sos(new int[][]{{1, 0, 0}}, 1, 0, 0, 0))
                .bytes(EIGHT_TIMES_PLUS_ONE)
                .eoi()
                .toByteArray();

        int[][] result = decode(jpeg, delegate);

        assertEquals(1, result.length);
        assertArrayEquals(new int[]{129, 130, 130, 131}, result[0]);
        assertEquals(1, warnings.size());
        assertTrue(warnings.get(0).contains("no DC tables"), "Unexpected warning: " + warnings.get(0));
    }

    @Test
    void decodeWithDcTableDoesNotWarn() throws IOException {
        List<String> warnings = new ArrayList<>();
        JPEGImageReader delegate = warningCollectingReader(warnings);

        byte[] jpeg = new JpegStream()
                .soi()
                .segment(JPEG.DHT, dht(0, 0, ONE_CODE_OF_LENGTH_7, new int[]{1}))
                .segment(JPEG.SOF3, sof(8, 2, 2, new int[][]{{1, 1, 1, 0}}))
                .segment(JPEG.SOS, sos(new int[][]{{1, 0, 0}}, 1, 0, 0, 0))
                .bytes(EIGHT_TIMES_PLUS_ONE)
                .eoi()
                .toByteArray();

        int[][] result = decode(jpeg, delegate);

        assertEquals(1, result.length);
        assertArrayEquals(new int[]{129, 130, 130, 131}, result[0]);
        assertTrue(warnings.isEmpty(), "Unexpected warnings: " + warnings);
    }

    @Test
    void decodeWithDnlSegment() throws IOException {
        // A lossless JPEG with unknown number of lines (0 in SOF) and a DNL segment, which is read
        // (and discarded) after the first scan. As the frame height is 0, no samples are output.
        byte[] jpeg = new JpegStream()
                .soi()
                .segment(JPEG.DHT, dht(0, 0, ONE_CODE_OF_LENGTH_1, new int[]{0}))
                .segment(JPEG.SOF3, sof(8, 2, 0, new int[][]{{1, 1, 1, 0}}))
                .segment(JPEG.SOS, sos(new int[][]{{1, 0, 0}}, 1, 0, 0, 0))
                .bytes(0xFF, 0xDC) // DNL marker, found while decoding the (missing) samples
                .bytes(0x00, 0x04, 0x00, 0x05) // DNL segment length (4) and the number of lines (5)
                .eoi()
                .toByteArray();

        JPEGLosslessDecoder decoder = newDecoder(jpeg);
        int[][] result = decoder.decode();

        assertEquals(1, result.length);
        assertEquals(0, result[0].length);
        assertEquals(0, decoder.getDimY());
    }

    @Test
    void decodeWithMalformedDnlSegmentThrowsIOException() throws IOException {
        byte[] jpeg = new JpegStream()
                .soi()
                .segment(JPEG.DHT, dht(0, 0, ONE_CODE_OF_LENGTH_1, new int[]{0}))
                .segment(JPEG.SOF3, sof(8, 2, 0, new int[][]{{1, 1, 1, 0}}))
                .segment(JPEG.SOS, sos(new int[][]{{1, 0, 0}}, 1, 0, 0, 0))
                .bytes(0xFF, 0xDC) // DNL marker
                .bytes(0x00, 0x05, 0x00, 0x05, 0x00) // DNL segment length 5 is illegal (must be 4)
                .eoi()
                .toByteArray();

        IOException exception = assertThrows(IOException.class, () -> decode(jpeg));

        assertNotNull(exception.getMessage());
        assertTrue(exception.getMessage().contains("Ld!=4"), "Unexpected message: " + exception.getMessage());
    }

    @Test
    void decodeNotJpegThrowsIIOException() {
        // A stream that does not start with SOI must be rejected before any decoding takes place
        byte[] notJpeg = new byte[]{0x00, 0x11, 0x22, 0x33, 0x44, 0x55};

        IOException exception = assertThrows(IOException.class, () -> decode(new ArrayList<Segment>(), notJpeg, null));

        assertTrue(exception instanceof IIOException, "Expected IIOException, was " + exception.getClass());
        assertNotNull(exception.getMessage());
        assertTrue(exception.getMessage().contains("0xFFD8"), "Unexpected message: " + exception.getMessage());
    }

    @Test
    void decodeEmptyStreamThrowsEOFException() {
        assertThrows(EOFException.class, () -> decode(new ArrayList<Segment>(), new byte[0], null));
    }

    private static JPEGLosslessDecoder newDecoder(byte[] jpeg) throws IOException {
        return newDecoder(parseSegments(jpeg), jpeg, null);
    }

    private static JPEGLosslessDecoder newDecoder(List<Segment> segments, byte[] data, JPEGImageReader listenerDelegate) {
        ImageInputStream input = new MemoryCacheImageInputStream(new ByteArrayInputStream(data));

        return new JPEGLosslessDecoder(segments, input, listenerDelegate);
    }

    private static int[][] decode(byte[] jpeg) throws IOException {
        return decode(parseSegments(jpeg), jpeg, null);
    }

    private static int[][] decode(byte[] jpeg, JPEGImageReader listenerDelegate) throws IOException {
        return decode(parseSegments(jpeg), jpeg, listenerDelegate);
    }

    private static int[][] decode(List<Segment> segments, byte[] data, JPEGImageReader listenerDelegate) throws IOException {
        ImageInputStream input = new MemoryCacheImageInputStream(new ByteArrayInputStream(data));

        try {
            return new JPEGLosslessDecoder(segments, input, listenerDelegate).decode();
        }
        finally {
            input.close();
        }
    }

    private static JPEGImageReader warningCollectingReader(final List<String> warnings) {
        JPEGImageReader reader = new JPEGImageReader(new JPEGImageReaderSpi(), mock(ImageReader.class));
        reader.addIIOReadWarningListener(new IIOReadWarningListener() {
            @Override
            public void warningOccurred(ImageReader source, String warning) {
                warnings.add(warning);
            }
        });

        return reader;
    }

    private static List<Segment> parseSegments(byte[] jpeg) throws IOException {
        List<Segment> segments = new ArrayList<>();
        DataInputStream stream = new DataInputStream(new ByteArrayInputStream(jpeg));

        assertEquals(JPEG.SOI, stream.readUnsignedShort(), "Test stream does not start with SOI");

        while (true) {
            int marker = stream.readUnsignedShort();

            if (marker == JPEG.SOS || marker == JPEG.EOI) {
                return segments;
            }

            int length = stream.readUnsignedShort();
            byte[] payload = new byte[length - 2];
            stream.readFully(payload);

            segments.add(Segment.read(marker, "", length, new DataInputStream(new ByteArrayInputStream(payload))));
        }
    }

    private static byte[] dht(int tableClass, int tableId, int[] codeLengthCounts, int[] values) {
        byte[] payload = new byte[1 + 16 + values.length];
        payload[0] = (byte) ((tableClass << 4) | tableId);

        for (int i = 0; i < 16; i++) {
            payload[1 + i] = (byte) codeLengthCounts[i];
        }

        for (int i = 0; i < values.length; i++) {
            payload[1 + 16 + i] = (byte) values[i];
        }

        return payload;
    }

    private static byte[] sof(int precision, int width, int height, int[][] components) {
        // Each component is {id, hSub, vSub, qtSel}
        byte[] payload = new byte[6 + components.length * 3];
        payload[0] = (byte) precision;
        payload[1] = (byte) (height >> 8);
        payload[2] = (byte) height;
        payload[3] = (byte) (width >> 8);
        payload[4] = (byte) width;
        payload[5] = (byte) components.length;

        for (int i = 0; i < components.length; i++) {
            payload[6 + i * 3] = (byte) components[i][0];
            payload[7 + i * 3] = (byte) ((components[i][1] << 4) | components[i][2]);
            payload[8 + i * 3] = (byte) components[i][3];
        }

        return payload;
    }

    private static byte[] sos(int[][] components, int spectralSelStart, int spectralSelEnd, int approxHigh, int approxLow) {
        // Each component is {scanCompSel, dcTabSel, acTabSel}
        byte[] payload = new byte[4 + components.length * 2];
        payload[0] = (byte) components.length;

        for (int i = 0; i < components.length; i++) {
            payload[1 + i * 2] = (byte) components[i][0];
            payload[2 + i * 2] = (byte) ((components[i][1] << 4) | components[i][2]);
        }

        int index = 1 + components.length * 2;
        payload[index] = (byte) spectralSelStart;
        payload[index + 1] = (byte) spectralSelEnd;
        payload[index + 2] = (byte) ((approxHigh << 4) | approxLow);

        return payload;
    }

    /** Simple builder for JPEG streams. */
    private static final class JpegStream {
        private final ByteArrayOutputStream out = new ByteArrayOutputStream();

        JpegStream soi() {
            return marker(JPEG.SOI);
        }

        JpegStream eoi() {
            return marker(JPEG.EOI);
        }

        JpegStream marker(int marker) {
            out.write((marker >> 8) & 0xFF);
            out.write(marker & 0xFF);

            return this;
        }

        JpegStream segment(int marker, byte[] payload) {
            marker(marker);

            int length = payload.length + 2;
            out.write((length >> 8) & 0xFF);
            out.write(length & 0xFF);
            out.write(payload, 0, payload.length);

            return this;
        }

        JpegStream bytes(int... values) {
            for (int value : values) {
                out.write(value & 0xFF);
            }

            return this;
        }

        byte[] toByteArray() {
            return out.toByteArray();
        }
    }
}
