    @Test
    void decodeUnknownScanComponentThrowsIllegalArgumentException() throws IOException {
        // The scan selects component 2, which is not defined in the frame (only component 1 is)
        byte[] jpeg = new JpegStream()
                .soi()
                .segment(JPEG.DHT, dht(0, 0, ONE_CODE_OF_LENGTH_7, new int[]{1}))
                .segment(JPEG.SOF3, sof(8, 2, 2, new int[][]{{1, 1, 1, 0}}))
                .segment(JPEG.SOS, sos(new int[][]{{2, 0, 0}}, 1, 0, 0, 0))
                .bytes(EIGHT_TIMES_PLUS_ONE)
                .eoi()
                .toByteArray();

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> decode(jpeg));

        assertNotNull(exception.getMessage());
        assertTrue(exception.getMessage().contains("No such component id"), "Unexpected message: " + exception.getMessage());
    }

    private static JPEGLosslessDecoder newDecoder(byte[] jpeg) throws IOException {
        return newDecoder(parseSegments(jpeg), jpeg, null);
    }

    private static JPEGLosslessDecoder newDecoder(List<Segment> segments, byte[] data, JPEGImageReader listenerDelegate) {
        ImageInputStream input = new MemoryCacheImageInputStream(new ByteArrayInputStream(data));

        return new JPEGLosslessDecoder(segments, input, listenerDelegate);
    }

    private static int[][] decode(byte[] jpeg) throws IOException {
        return decode(parseSegments(jpeg), jpeg, null);
    }

