final class PCXHeader {
    private static final IndexColorModel MONOCHROME = new IndexColorModel(1, 2, new int[] {0, -1}, 0, false, -1, DataBuffer.TYPE_BYTE);

    private int version;
    private int compression;
    private int bitsPerPixel;
    private int width;
