import com.twelvemonkeys.imageio.plugins.pcx.PCXImageReader;
import com.twelvemonkeys.imageio.plugins.pcx.PCXImageReaderSpi;
import javax.imageio.*;
import javax.imageio.event.*;
import javax.imageio.stream.*;
import java.awt.*;
import java.awt.image.*;
import java.io.*;
import java.util.*;

public class Probe {
    static final File ROSE = new File("/testbed/imageio/imageio-pcx/src/test/resources/pcx/rose.pcx");
    static final File INPUT = new File("/testbed/imageio/imageio-pcx/src/test/resources/pcx/input.pcx");
    static final File ANIMALS = new File("/testbed/imageio/imageio-pcx/src/test/resources/pcx/animals.pcx");

    static PCXImageReader reader(File f) throws IOException {
        PCXImageReader r = new PCXImageReader(new PCXImageReaderSpi());
        r.setInput(ImageIO.createImageInputStream(f));
        return r;
    }

    static void subsampling(File f) throws IOException {
        System.out.println("--- subsampling " + f.getName());
        PCXImageReader full = reader(f);
        BufferedImage ref = full.read(0, null);
        for (int xsub = 1; xsub <= 3; xsub++) {
            for (int ysub = 1; ysub <= 3; ysub++) {
                for (int ox = 0; ox < xsub; ox++) {
                    for (int oy = 0; oy < ysub; oy++) {
                        PCXImageReader r = reader(f);
                        ImageReadParam p = r.getDefaultReadParam();
                        p.setSourceSubsampling(xsub, ysub, ox, oy);
                        BufferedImage img;
                        try {
                            img = r.read(0, p);
                        } catch (Exception e) {
                            System.out.println("  sub " + xsub + "," + ysub + " off " + ox + "," + oy + " -> " + e);
                            continue;
                        }
                        int expW = (ref.getWidth() - ox + xsub - 1) / xsub;
                        int expH = (ref.getHeight() - oy + ysub - 1) / ysub;
                        boolean ok = img.getWidth() == expW && img.getHeight() == expH;
                        // sample pixel equality
                        int bad = 0;
                        for (int y = 0; y < img.getHeight(); y += 7) {
                            for (int x = 0; x < img.getWidth(); x += 5) {
                                int sx = ox + x * xsub, sy = oy + y * ysub;
                                if (sx < ref.getWidth() && sy < ref.getHeight()) {
                                    if (img.getRGB(x, y) != ref.getRGB(sx, sy)) bad++;
                                }
                            }
                        }
                        System.out.println("  sub " + xsub + "," + ysub + " off " + ox + "," + oy + " dims " + img.getWidth() + "x" + img.getHeight() + " exp " + expW + "x" + expH + " ok=" + ok + " mismatch=" + bad);
                    }
                }
            }
        }
    }

    static void region(File f) throws IOException {
        System.out.println("--- region " + f.getName());
        PCXImageReader full = reader(f);
        BufferedImage ref = full.read(0, null);
        Rectangle[] rects = { new Rectangle(0,0,1,1), new Rectangle(1,1,ref.getWidth()-1, ref.getHeight()-1), new Rectangle(ref.getWidth()/2, 0, ref.getWidth()/2, ref.getHeight()), new Rectangle(0,0,ref.getWidth(),ref.getHeight()), new Rectangle(3,4,5,6) };
        for (Rectangle rect : rects) {
            PCXImageReader r = reader(f);
            ImageReadParam p = r.getDefaultReadParam();
            p.setSourceRegion(rect);
            try {
                BufferedImage img = r.read(0, p);
                int bad = 0;
                for (int y = 0; y < img.getHeight(); y++)
                    for (int x = 0; x < img.getWidth(); x++)
                        if (img.getRGB(x,y) != ref.getRGB(x+rect.x, y+rect.y)) bad++;
                System.out.println("  rect " + rect + " -> " + img.getWidth() + "x" + img.getHeight() + " mismatch=" + bad);
            } catch (Exception e) {
                System.out.println("  rect " + rect + " -> " + e);
            }
        }
    }

    static void bands(File f) throws IOException {
        System.out.println("--- destbands " + f.getName());
        PCXImageReader r0 = reader(f);
        System.out.println("  raw bands=" + r0.getRawImageType(0).getNumBands());
        PCXImageReader r = reader(f);
        ImageReadParam p = r.getDefaultReadParam();
        try {
            p.setDestinationBands(new int[]{0});
            BufferedImage img = r.read(0, p);
            System.out.println("  destBands[0] -> ok bands=" + img.getRaster().getNumBands());
        } catch (Exception e) {
            System.out.println("  destBands[0] -> " + e);
        }
        PCXImageReader r2 = reader(f);
        ImageReadParam p2 = r2.getDefaultReadParam();
        try {
            p2.setSourceBands(new int[]{0, 1});
            BufferedImage img = r2.read(0, p2);
            System.out.println("  srcBands[0,1] -> ok bands=" + img.getRaster().getNumBands());
        } catch (Exception e) {
            System.out.println("  srcBands[0,1] -> " + e);
        }
    }

    static void abort(File f) throws IOException {
        System.out.println("--- abort " + f.getName());
        final List<String> events = new ArrayList<>();
        PCXImageReader r = reader(f);
        r.addIIOReadProgressListener(new IIOReadProgressListener() {
            public void sequenceStarted(ImageReader source, int minIndex) { events.add("seqStart"); }
            public void sequenceComplete(ImageReader source) { events.add("seqComplete"); }
            public void imageStarted(ImageReader source, int imageIndex) { events.add("start"); }
            public void imageProgress(ImageReader source, float percentageDone) { events.add("progress " + percentageDone); }
            public void imageComplete(ImageReader source) { events.add("complete"); }
            public void thumbnailStarted(ImageReader source, int imageIndex, int thumbnailIndex) {}
            public void thumbnailProgress(ImageReader source, float percentageDone) {}
            public void thumbnailComplete(ImageReader source) {}
            public void readAborted(ImageReader source) { events.add("aborted"); }
        });
        r.abort();
        try {
            BufferedImage img = r.read(0, null);
            System.out.println("  aborted read -> " + img + " w=" + img.getWidth());
        } catch (Exception e) {
            System.out.println("  aborted read -> " + e);
        }
        System.out.println("  events=" + events);
    }

    static void eventsNormal(File f) throws IOException {
        System.out.println("--- events normal " + f.getName());
        final List<String> events = new ArrayList<>();
        PCXImageReader r = reader(f);
        r.addIIOReadProgressListener(new IIOReadProgressListener() {
            public void sequenceStarted(ImageReader source, int minIndex) { events.add("seqStart"); }
            public void sequenceComplete(ImageReader source) { events.add("seqComplete"); }
            public void imageStarted(ImageReader source, int imageIndex) { events.add("start"); }
            public void imageProgress(ImageReader source, float percentageDone) { events.add("p" + percentageDone); }
            public void imageComplete(ImageReader source) { events.add("complete"); }
            public void thumbnailStarted(ImageReader source, int imageIndex, int thumbnailIndex) {}
            public void thumbnailProgress(ImageReader source, float percentageDone) {}
            public void thumbnailComplete(ImageReader source) {}
            public void readAborted(ImageReader source) { events.add("aborted"); }
        });
        r.read(0, null);
        System.out.println("  events=" + events.subList(0, Math.min(5, events.size())) + " ... last=" + events.get(events.size()-1) + " size=" + events.size());
    }

    public static void main(String[] args) throws Exception {
        subsampling(ROSE);
        subsampling(INPUT);
        region(ROSE);
        region(INPUT);
        region(ANIMALS);
        bands(INPUT);
        bands(ROSE);
        abort(INPUT);
        eventsNormal(INPUT);
        eventsNormal(ROSE);
    }
}
