import com.twelvemonkeys.imageio.plugins.pcx.PCXImageReader;
import com.twelvemonkeys.imageio.plugins.pcx.PCXImageReaderSpi;
import com.twelvemonkeys.imageio.stream.ByteArrayImageInputStream;
import javax.imageio.ImageReadParam;
import javax.imageio.ImageTypeSpecifier;
import javax.imageio.stream.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.util.Iterator;

public class Synth {

    static byte[] pcx(int version, int encoding, int bpp, int width, int height,
                      byte[] egaPalette, int channels, int bytesPerLine, byte[] data) throws IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        DataOutputStream d = new DataOutputStream(out);
        d.writeByte(0x0A);
        d.writeByte(version);
        d.writeByte(encoding);
        d.writeByte(bpp);
        writeLE16(d, 0); // xStart
        writeLE16(d, 0); // yStart
        writeLE16(d, width - 1);
        writeLE16(d, height - 1);
        writeLE16(d, 72);
        writeLE16(d, 72);
        d.write(egaPalette);
        d.writeByte(0); // reserved
        d.writeByte(channels);
        writeLE16(d, bytesPerLine);
        writeLE16(d, 1); // paletteInfo
        writeLE16(d, width);
        writeLE16(d, height);
        for (int i = 0; i < 54; i++) d.writeByte(0);
        d.write(data);
        return out.toByteArray();
    }

    static void writeLE16(DataOutputStream d, int v) throws IOException {
        d.writeByte(v & 0xFF);
        d.writeByte((v >> 8) & 0xFF);
    }

    static byte[] egaPalette() {
        byte[] p = new byte[48];
        for (int i = 0; i < 16; i++) {
            p[i*3] = (byte) (i * 16);
            p[i*3+1] = (byte) (255 - i * 16);
            p[i*3+2] = (byte) (i * 8);
        }
        return p;
    }

    static void show(String label, byte[] bytes) throws IOException {
        System.out.println("=== " + label + " len=" + bytes.length);
        PCXImageReader r = new PCXImageReader(new PCXImageReaderSpi());
        r.setInput(new ByteArrayImageInputStream(bytes));
        System.out.println("  w=" + r.getWidth(0) + " h=" + r.getHeight(0) + " raw=" + r.getRawImageType(0) + " rawBands=" + r.getRawImageType(0).getNumBands());
        Iterator<ImageTypeSpecifier> it = r.getImageTypes(0);
        while (it.hasNext()) System.out.println("  type=" + it.next());
        try {
            BufferedImage img = r.read(0, null);
            System.out.println("  image=" + img.getWidth() + "x" + img.getHeight() + " type=" + img.getType() + " bands=" + img.getRaster().getNumBands() + " sm=" + img.getRaster().getSampleModel().getClass().getSimpleName());
            StringBuilder sb = new StringBuilder();
            for (int y = 0; y < img.getHeight(); y++) {
                for (int x = 0; x < img.getWidth(); x++) {
                    sb.append(img.getRaster().getNumBands() == 1 ? String.format("%02x ", img.getRaster().getSample(x, y, 0)) : String.format("%08x ", img.getRGB(x, y)));
                }
                sb.append("\n     ");
            }
            System.out.println("  pixels: " + sb);
        } catch (Exception e) {
            System.out.println("  FAILED: " + e);
        }
    }

    public static void main(String[] args) throws IOException {
        // 8bpp grayscale, 1 channel, uncompressed
        int w = 5, h = 3, bpl = 6;
        byte[] data = new byte[bpl * h];
        for (int i = 0; i < data.length; i++) data[i] = (byte) (i * 10);
        show("8bpp 1channel none", pcx(5, 0, 8, w, h, egaPalette(), 1, bpl, data));

        // 2bpp indexed 1 channel, packed 4 pixels per byte, bytesPerLine 2 -> rowWidth 8
        byte[] data2 = new byte[2 * 2];
        data2[0] = (byte) 0x1B; // 00 01 10 11
        data2[1] = (byte) 0xE4; // 11 10 01 00
        data2[2] = (byte) 0x55;
        data2[3] = (byte) 0xAA;
        show("2bpp 1channel none", pcx(5, 0, 2, 8, 2, egaPalette(), 1, 2, data2));

        // 4bpp indexed 1 channel
        byte[] data4 = new byte[2 * 2];
        data4[0] = (byte) 0x12; data4[1] = (byte) 0x34;
        data4[2] = (byte) 0xAB; data4[3] = (byte) 0xCD;
        show("4bpp 1channel none", pcx(5, 0, 4, 4, 2, egaPalette(), 1, 2, data4));

        // 1bpp 3 planes bitplane: planeWidth=2, row = 3 planes * 2 bytes
        byte[] dataBp = new byte[2 * 3 * 2];
        // row 0: plane0 = A0 03, plane1 = 0, plane2 = 0
        dataBp[0] = (byte) 0xA0; dataBp[1] = 0x03;
        // row 1: plane0 = 0, plane1 = F0, plane2 = 0F
        dataBp[6] = 0x00; dataBp[7] = 0x00;
        dataBp[8] = (byte) 0xF0; dataBp[9] = 0x00;
        dataBp[10] = 0x0F; dataBp[11] = 0x00;
        show("1bpp 3 planes", pcx(5, 0, 1, 16, 2, egaPalette(), 3, 2, dataBp));

        // 24bpp
        byte[] data24 = new byte[3 * 2];
        data24[0] = 1; data24[1] = 2; data24[2] = 3;
        data24[3] = 4; data24[4] = 5; data24[5] = 6;
        show("24bpp", pcx(5, 0, 24, 2, 1, egaPalette(), 3, 6, data24));

        // 32bpp
        byte[] data32 = new byte[4];
        data32[0] = 1; data32[1] = 2; data32[2] = 3; data32[3] = 4;
        show("32bpp", pcx(5, 0, 32, 1, 1, egaPalette(), 4, 4, data32));

        // channels 9 with 1bpp
        byte[] data9 = new byte[16];
        show("1bpp 9 planes", pcx(5, 0, 1, 8, 1, egaPalette(), 9, 1, data9));

        // huge dims
        show("huge dims", pcx(5, 0, 8, 5000, 5000, egaPalette(), 1, 5000, new byte[16]));

        // RLE 8bpp grayscale
        byte[] rle = new byte[]{ 0x05, 0x7F, (byte) 0xC3, 0x42, 0x11 };
        show("8bpp RLE", pcx(5, 1, 8, 8, 1, egaPalette(), 1, 8, rle));
    }
}
