        data4[2] = (byte) 0xAB; data4[3] = (byte) 0xCD;
        show("4bpp 1channel none", pcx(5, 0, 4, 4, 2, egaPalette(), 1, 2, data4));

        // 1bpp 3 planes bitplane: planeWidth=2, row = 3 planes * 2 bytes
        byte[] dataBp = new byte[2 * 3 * 2];
        // row 0: plane0 = A0 03, plane1 = 0, plane2 = 0
        dataBp[0] = (byte) 0xA0; dataBp[1] = 0x03;
        // row 1: plane0 = 0, plane1 = F0, plane2 = 0F
        dataBp[6] = 0x00; dataBp[7] = 0x00;
        dataBp[8] = (byte) 0xF0; dataBp[9] = 0x00;
        dataBp[10] = 0x0F; dataBp[11] = 0x00;
        show("1bpp 3 planes", pcx(5, 0, 1, 16, 2, egaPalette(), 3, 2, dataBp));

        // 24bpp
        byte[] data24 = new byte[3 * 2];
        data24[0] = 1; data24[1] = 2; data24[2] = 3;
        data24[3] = 4; data24[4] = 5; data24[5] = 6;
        show("24bpp", pcx(5, 0, 24, 2, 1, egaPalette(), 3, 6, data24));

        // 32bpp
        byte[] data32 = new byte[4];
        data32[0] = 1; data32[1] = 2; data32[2] = 3; data32[3] = 4;
        show("32bpp", pcx(5, 0, 32, 1, 1, egaPalette(), 4, 4, data32));

        // channels 9 with 1bpp
        byte[] data9 = new byte[16];
        show("1bpp 9 planes", pcx(5, 0, 1, 8, 1, egaPalette(), 9, 1, data9));

        // huge dims
        show("huge dims", pcx(5, 0, 8, 5000, 5000, egaPalette(), 1, 5000, new byte[16]));

        // RLE 8bpp grayscale
        byte[] rle = new byte[]{ 0x05, 0x7F, (byte) 0xC3, 0x42, 0x11 };
