        System.out.println("  img type=" + img.getType() + " px(0,0)=" + Integer.toHexString(img.getRGB(0,0)) + " px(1,0)=" + Integer.toHexString(img.getRGB(1,0)) + " px(2,0)=" + Integer.toHexString(img.getRGB(2,0)) + " px(1,1)=" + Integer.toHexString(img.getRGB(1,1)));
        // second read
        BufferedImage img2 = r.read(0, null);
        System.out.println("  second read equal=" + (img2.getRGB(1,0) == img.getRGB(1,0)));

        // 2. Unknown-length stream
        byte[] inputPcx = java.nio.file.Files.readAllBytes(new File("/testbed/imageio/imageio-pcx/src/test/resources/pcx/input.pcx").toPath());
        ImageInputStream unk = new MemoryCacheImageInputStream(new ByteArrayInputStream(inputPcx));
        System.out.println("unknown len=" + unk.length());
        PCXImageReader r2 = new PCXImageReader(new PCXImageReaderSpi());
        r2.setInput(unk);
        BufferedImage i2 = r2.read(0, null);
        System.out.println("  read=" + i2.getWidth() + "x" + i2.getHeight() + " px=" + Integer.toHexString(i2.getRGB(0,0)));

