            PCXImageReader rr = new PCXImageReader(new PCXImageReaderSpi());
            rr.setInput(new ByteArrayImageInputStream((byte[]) tc[1]));
            try {
                BufferedImage im = rr.read(0, null);
                System.out.println("  " + tc[0] + " len=" + ((byte[]) tc[1]).length + " -> ok " + im.getWidth() + "x" + im.getHeight() + " px(0,0)=" + im.getRaster().getSample(0,0,0) + " px(199,99)=" + im.getRaster().getSample(199,99,0));
            } catch (Exception e) {
                System.out.println("  " + tc[0] + " len=" + ((byte[]) tc[1]).length + " -> " + e);
            }
        }

        // 4. RLE 64x64 grey
        int rw = 64, rh = 64;
        byte[] rle = new byte[(2 + 2) * rh];
        for (int y = 0; y < rh; y++) {
            rle[y*4] = (byte) 0xFF; rle[y*4+1] = (byte) (y % 256);      // 63 x value
            rle[y*4+2] = (byte) 0xC1; rle[y*4+3] = (byte) (y);          // 1 x value
        }
        PCXImageReader r3 = new PCXImageReader(new PCXImageReaderSpi());
        byte[] rleBytes = Synth.pcx(5, 1, 8, rw, rh, Synth.egaPalette(), 1, rw, rle);
        r3.setInput(new ByteArrayImageInputStream(rleBytes));
        try {
            BufferedImage im = r3.read(0, null);
            System.out.println("RLE len=" + rleBytes.length + " -> " + im.getWidth() + "x" + im.getHeight() + " px(0,0)=" + im.getRaster().getSample(0,0,0) + " px(63,0)=" + im.getRaster().getSample(63,0,0) + " px(0,5)=" + im.getRaster().getSample(0,5,0) + " px(62,5)=" + im.getRaster().getSample(62,5,0) + " px(63,5)=" + im.getRaster().getSample(63,5,0));
        } catch (Exception e) {
            System.out.println("RLE -> " + e);
        }

        // 5. bitplanes with identical rows
        int bpw = 16, bph = 3, bpbpl = 2;
        byte[] bpd = new byte[bpbpl * 3 * bph];
        for (int y = 0; y < bph; y++) {
            bpd[y * 6] = (byte) 0xA0;
            bpd[y * 6 + 1] = 0x03;
        }
        byte[] bpBytes = Synth.pcx(5, 0, 1, bpw, bph, Synth.egaPalette(), 3, bpbpl, bpd);
        PCXImageReader r4 = new PCXImageReader(new PCXImageReaderSpi());
        r4.setInput(new ByteArrayImageInputStream(bpBytes));
        BufferedImage bp = r4.read(0, null);
        for (int y = 0; y < bph; y++) {
            StringBuilder sb = new StringBuilder();
            for (int x = 0; x < bpw; x++) sb.append(bp.getRaster().getSample(x, y, 0)).append(' ');
            System.out.println("bitplane row " + y + ": " + sb);
        }
        // 6. abort on 24bpp
        int aw = 2, ah = 4;
        byte[] ad = new byte[6 * ah];
        PCXImageReader r5 = new PCXImageReader(new PCXImageReaderSpi());
        r5.setInput(new ByteArrayImageInputStream(Synth.pcx(5, 0, 24, aw, ah, Synth.egaPalette(), 3, 6, ad)));
        r5.abort();
        System.out.println("abort 24bpp -> " + r5.read(0, null).getWidth());

        // 7. invalid bpp
        PCXImageReader r6 = new PCXImageReader(new PCXImageReaderSpi());
        r6.setInput(new ByteArrayImageInputStream(Synth.pcx(5, 0, 3, 8, 1, Synth.egaPalette(), 1, 1, new byte[4])));
        try { r6.read(0, null); } catch (Exception e) { System.out.println("bpp=3 -> " + e); }

        // 8. source region out of bounds
        PCXImageReader r7 = new PCXImageReader(new PCXImageReaderSpi());
        r7.setInput(new ByteArrayImageInputStream(Synth.pcx(5, 0, 8, 8, 8, Synth.egaPalette(), 1, 8, new byte[64])));
        ImageReadParam p = r7.getDefaultReadParam();
        p.setSourceRegion(new java.awt.Rectangle(4, 4, 8, 8));
        try { BufferedImage im = r7.read(0, p); System.out.println("oob region -> ok " + im.getWidth() + "x" + im.getHeight()); } catch (Exception e) { System.out.println("oob region -> " + e); }

        // 9. empty region
        PCXImageReader r8 = new PCXImageReader(new PCXImageReaderSpi());
        r8.setInput(new ByteArrayImageInputStream(Synth.pcx(5, 0, 8, 8, 8, Synth.egaPalette(), 1, 8, new byte[64])));
        ImageReadParam p2 = r8.getDefaultReadParam();
        p2.setSourceRegion(new java.awt.Rectangle(0, 0, 0, 0));
        try { BufferedImage im = r8.read(0, p2); System.out.println("empty region -> ok " + im); } catch (Exception e) { System.out.println("empty region -> " + e); }

        // 10. destination image supplied
        PCXImageReader r9 = new PCXImageReader(new PCXImageReaderSpi());
        r9.setInput(new ByteArrayImageInputStream(Synth.pcx(5, 0, 8, 8, 8, Synth.egaPalette(), 1, 8, new byte[64])));
        ImageReadParam p3 = r9.getDefaultReadParam();
        BufferedImage dest = new BufferedImage(8, 8, BufferedImage.TYPE_INT_RGB);
        p3.setDestination(dest);
        BufferedImage im = r9.read(0, p3);
        System.out.println("explicit dest -> same=" + (im == dest) + " px=" + Integer.toHexString(im.getRGB(0,0)));
    }
}
