        // resources loop
        String[] names = {"input.pcx","animals.pcx","DARKSTAR.PCX","CGA_RGBI.PCX","CGA_BW.PCX","MARBLES.PCX","GMARBLES.PCX","no-palette-monochrome.pcx","rose.pcx","CGA_TST1.PCX","CGA_FSD.PCX"};
        for (String n : names) {
            File f = new File("/testbed/imageio/imageio-pcx/src/test/resources/pcx/" + n);
            PCXImageReader rr = new PCXImageReader(new PCXImageReaderSpi());
            rr.setInput(ImageIO.createImageInputStream(f));
            try {
                BufferedImage im = rr.read(0, null);
                IndexColorModel icm = im.getColorModel() instanceof IndexColorModel ? (IndexColorModel) im.getColorModel() : null;
                int[] px = samples(im, new Rectangle(0,0,im.getWidth(),im.getHeight()));
                int max = 0;
                for (int v : px) max = Math.max(max, v);
                System.out.println(n + " -> " + im.getWidth() + "x" + im.getHeight() + " type=" + im.getType() + " bands=" + im.getRaster().getNumBands() + " mapSize=" + (icm != null ? icm.getMapSize() : -1) + " maxSample=" + max);
            } catch (Exception e) {
                System.out.println(n + " -> " + e);
            }
        }
    }
    static int[] samples(BufferedImage img, Rectangle rect) {
        return img.getRaster().getPixels(rect.x, rect.y, rect.width, rect.height, (int[]) null);
    }
}
