/**
 * Tests for {@link PCXImageReader#read(int, ImageReadParam)}.
 * <p>
 * The tests cover the three decoding branches of the reader (indexed/bit-planed, true color
 * 24/32 bits per pixel and banded/byte data), the {@code ImageReadParam} handling
 * (subsampling, source region, destination type, destination bands), the
 * input size validation and the progress/abort protocol.
 * </p>
 */
public class PCXImageReaderReadTests {

    private final List<ImageReader> readers = new ArrayList<>();

    @AfterEach
    public void disposeReaders() throws IOException {
        for (ImageReader reader : readers) {
            Object input = reader.getInput();
            reader.dispose();
            if (input instanceof ImageInputStream) {
                ((ImageInputStream) input).close();
            }
        }
        readers.clear();
    }

    // ---------------------------------------------------------------------------------------------
    // Normal cases, all decode branches
    // ---------------------------------------------------------------------------------------------

    @Test
    public void testReadWithNullParam() throws Exception {
        PCXImageReader reader = newReaderForResource("pcx/input.pcx");

        BufferedImage image = reader.read(0, null);

        assertNotNull(image);
        assertEquals(reader.getWidth(0), image.getWidth());
        assertEquals(reader.getHeight(0), image.getHeight());
        // Three banded 8 bit channels are read into the first (interleaved BGR) image type
        assertEquals(BufferedImage.TYPE_3BYTE_BGR, image.getType());
        assertEquals(3, image.getRaster().getNumBands());
    }

    @Test
    public void testReadWithDefaultParamIsIdenticalToNullParam() throws Exception {
        PCXImageReader reader = newReaderForResource("pcx/rose.pcx");

        BufferedImage fromNull = reader.read(0, null);
        BufferedImage fromDefault = reader.read(0, reader.getDefaultReadParam());

        assertEquals(fromNull.getWidth(), fromDefault.getWidth());
        assertEquals(fromNull.getHeight(), fromDefault.getHeight());
        assertEquals(fromNull.getType(), fromDefault.getType());
        assertArrayEquals(samples(fromNull), samples(fromDefault));
    }

    @Test
    public void testReadTwiceFromSameReaderIsRepeatable() throws Exception {
        PCXImageReader reader = newReaderForResource("pcx/input.pcx");

        BufferedImage first = reader.read(0, null);
        BufferedImage second = reader.read(0, null);

        assertEquals(first.getWidth(), second.getWidth());
        assertEquals(first.getHeight(), second.getHeight());
        assertArrayEquals(samples(first), samples(second));
    }

    @Test
    public void testReadIndexedImageKeepsPalette() throws Exception {
        PCXImageReader reader = newReaderForResource("pcx/rose.pcx");

        BufferedImage image = reader.read(0, null);

        assertEquals(BufferedImage.TYPE_BYTE_BINARY, image.getType());
        IndexColorModel colorModel = assertInstanceOf(IndexColorModel.class, image.getColorModel());
        assertEquals(16, colorModel.getMapSize());

        // 4 bits per pixel, all indexes must be within the palette
        for (int value : samples(image)) {
            assertTrue(value >= 0 && value < 16, "Index out of palette range: " + value);
        }
    }

    @Test
    public void testReadUncompressedByteImage() throws IOException {
        int width = 5;
        int height = 3;
        int bytesPerLine = 6;
        byte[] data = new byte[bytesPerLine * height];

        for (int i = 0; i < data.length; i++) {
            data[i] = (byte) (i * 10);
        }

        PCXImageReader reader = newReader(createPCX(PCX.VERSION_3, PCX.COMPRESSION_NONE, 8, 1, width, height, bytesPerLine, defaultEGAPalette(), data));

        BufferedImage image = reader.read(0, null);

        assertEquals(BufferedImage.TYPE_BYTE_GRAY, image.getType());
        assertEquals(width, image.getWidth());
        assertEquals(height, image.getHeight());

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                assertEquals(data[y * bytesPerLine + x] & 0xFF, image.getRaster().getSample(x, y, 0),
                        "Pixel (" + x + ", " + y + ")");
            }
        }
    }

    @Test
    public void testReadTwoBitImageUnpacksPixelsMostSignificantBitFirst() throws IOException {
        int width = 8;
        int height = 2;
        byte[] data = new byte[]{
                (byte) 0x1B, (byte) 0xE4, // 00 01 10 11  11 10 01 00
                (byte) 0x55, (byte) 0xAA  // 01 01 01 01  10 10 10 10
        };

        PCXImageReader reader = newReader(createPCX(PCX.VERSION_3, PCX.COMPRESSION_NONE, 2, 1, width, height, 2, defaultEGAPalette(), data));

        BufferedImage image = reader.read(0, null);

        assertEquals(BufferedImage.TYPE_BYTE_BINARY, image.getType());
        assertEquals(width, image.getWidth());
        assertEquals(height, image.getHeight());
        assertArrayEquals(
                new int[]{0, 1, 2, 3, 3, 2, 1, 0,
                          1, 1, 1, 1, 2, 2, 2, 2},
                samples(image)
        );
    }

