        byte[] data = new byte[]{
                1, 2, 3, 4 // B G R A
        };

        PCXImageReader reader = newReader(createPCX(PCX.VERSION_3, PCX.COMPRESSION_NONE, 32, 4, width, height, 4, defaultEGAPalette(), data));

