    @Test
    public void testReadWithSourceRegion() throws Exception {
        PCXImageReader referenceReader = newReaderForResource("pcx/input.pcx");
        BufferedImage full = referenceReader.read(0, null);

        Rectangle[] regions = {
                new Rectangle(0, 0, 1, 1),
                new Rectangle(3, 4, 5, 6),
                new Rectangle(35, 0, 35, 46),
                new Rectangle(1, 1, 69, 45),
                new Rectangle(0, 0, 70, 46)
        };

        for (Rectangle region : regions) {
            PCXImageReader reader = newReaderForResource("pcx/input.pcx");
            ImageReadParam param = reader.getDefaultReadParam();
            param.setSourceRegion(region);

            BufferedImage image = reader.read(0, param);

            assertEquals(region.width, image.getWidth(), "Width for region " + region);
            assertEquals(region.height, image.getHeight(), "Height for region " + region);
            assertArrayEquals(
                    samples(full, region),
                    samples(image),
                    "Pixels for region " + region
            );
        }
    }

    @Test
    public void testReadWithOutOfBoundsSourceRegionIsClipped() throws IOException {
        byte[] data = new byte[64];
        for (int i = 0; i < data.length; i++) {
            data[i] = (byte) (i + 1);
        }

        byte[] pcx = createPCX(PCX.VERSION_3, PCX.COMPRESSION_NONE, 8, 1, 8, 8, 8, defaultEGAPalette(), data);

        BufferedImage full = newReader(pcx).read(0, null);

        PCXImageReader reader = newReader(pcx);
        ImageReadParam param = reader.getDefaultReadParam();
        param.setSourceRegion(new Rectangle(4, 4, 8, 8));

        BufferedImage image = reader.read(0, param);

        assertEquals(4, image.getWidth());
        assertEquals(4, image.getHeight());
        assertArrayEquals(samples(full, new Rectangle(4, 4, 4, 4)), samples(image));
    }

    @Test
    public void testReadWithSubsamplingProducesExpectedDimensions() throws Exception {
        PCXImageReader sizeReader = newReaderForResource("pcx/input.pcx");
        int width = sizeReader.getWidth(0);
        int height = sizeReader.getHeight(0);

        for (int xSub = 1; xSub <= 3; xSub++) {
            for (int ySub = 1; ySub <= 3; ySub++) {
                for (int xOffset = 0; xOffset < xSub; xOffset++) {
                    for (int yOffset = 0; yOffset < ySub; yOffset++) {
                        PCXImageReader reader = newReaderForResource("pcx/input.pcx");
                        ImageReadParam param = reader.getDefaultReadParam();
                        param.setSourceSubsampling(xSub, ySub, xOffset, yOffset);

                        BufferedImage image = reader.read(0, param);

                        String message = "Subsampling " + xSub + "x" + ySub + " offset " + xOffset + "," + yOffset;
                        assertEquals(subsampledSize(width, xSub, xOffset), image.getWidth(), message);
                        assertEquals(subsampledSize(height, ySub, yOffset), image.getHeight(), message);
                    }
                }
            }
        }
    }

    @Test
    public void testReadWithSubsamplingSelectsEveryNthPixel() throws Exception {
        PCXImageReader referenceReader = newReaderForResource("pcx/input.pcx");
        BufferedImage full = referenceReader.read(0, null);

        int[][] subsampling = {{2, 1}, {1, 2}, {2, 2}, {3, 1}, {3, 3}};

        for (int[] subsample : subsampling) {
            int xSub = subsample[0];
            int ySub = subsample[1];

            PCXImageReader reader = newReaderForResource("pcx/input.pcx");
            ImageReadParam param = reader.getDefaultReadParam();
            param.setSourceSubsampling(xSub, ySub, 0, 0);

            BufferedImage image = reader.read(0, param);

            for (int y = 0; y < image.getHeight(); y++) {
                for (int x = 0; x < image.getWidth(); x++) {
                    assertEquals(full.getRGB(x * xSub, y * ySub), image.getRGB(x, y),
                            "Pixel (" + x + ", " + y + ") for subsampling " + xSub + "x" + ySub);
                }
            }
        }
    }

    @Test
    public void testReadTrueColorImageWithSourceRegion() throws IOException {
        int width = 4;
