    @Test
    public void testReadWithRawDestinationType() throws Exception {
        PCXImageReader reader = newReaderForResource("pcx/input.pcx");
        ImageTypeSpecifier rawType = reader.getRawImageType(0);

        ImageReadParam param = reader.getDefaultReadParam();
        param.setDestinationType(rawType);

        BufferedImage image = reader.read(0, param);

        assertEquals(rawType.getNumBands(), image.getRaster().getNumBands());
        assertEquals(rawType.getSampleModel().getClass(), image.getSampleModel().getClass());
        assertEquals(reader.getWidth(0), image.getWidth());
        assertEquals(reader.getHeight(0), image.getHeight());
    }

