    @Test
    public void testReadRejectsDeclaredSizeExceedingInputLength() throws IOException {
        int width = 200;
        int height = 100;
        byte[] data = new byte[width * height];

        byte[] complete = createPCX(PCX.VERSION_3, PCX.COMPRESSION_NONE, 8, 1, width, height, width, defaultEGAPalette(), data);
        byte[] truncated = Arrays.copyOf(complete, PCX.HEADER_SIZE);

        PCXImageReader reader = newReader(truncated);

        IIOException exception = assertThrows(IIOException.class, () -> reader.read(0, null));
        assertTrue(exception.getMessage().contains(String.valueOf(width * height)), exception.getMessage());
        assertTrue(exception.getMessage().contains("128:1"), exception.getMessage());
    }

    @Test
    public void testReadAcceptsDeclaredSizeWithinInputLength() throws IOException {
        int width = 200;
        int height = 100;
        byte[] data = new byte[width * height];
        for (int i = 0; i < data.length; i++) {
            data[i] = (byte) (i % 251);
        }

        byte[] complete = createPCX(PCX.VERSION_3, PCX.COMPRESSION_NONE, 8, 1, width, height, width, defaultEGAPalette(), data);

        BufferedImage image = newReader(complete).read(0, null);

        assertEquals(width, image.getWidth());
        assertEquals(height, image.getHeight());
        assertEquals(data[0] & 0xFF, image.getRaster().getSample(0, 0, 0));
        assertEquals(data[data.length - 1] & 0xFF, image.getRaster().getSample(width - 1, height - 1, 0));
    }

    @Test
    public void testReadRejectsTooManyBitPlanes() throws IOException {
        byte[] data = new byte[16];
        PCXImageReader reader = newReader(createPCX(PCX.VERSION_3, PCX.COMPRESSION_NONE, 1, 9, 8, 1, 9, defaultEGAPalette(), data));

        // Sanity check: the header is still considered a valid (indexed) image
        assertInstanceOf(IndexColorModel.class, reader.getRawImageType(0).getColorModel());

        IIOException exception = assertThrows(IIOException.class, () -> reader.read(0, null));
        assertTrue(exception.getMessage().contains("Unsupported number of bit planes"), exception.getMessage());
        assertTrue(exception.getMessage().contains("9"), exception.getMessage());
    }

