    @Test
    public void testReadAllSampleImages() throws Exception {
        String[] resources = {
                "pcx/input.pcx",
                "pcx/animals.pcx",
                "pcx/rose.pcx",
                "pcx/DARKSTAR.PCX",
                "pcx/CGA_BW.PCX",
                "pcx/CGA_FSD.PCX",
                "pcx/CGA_RGBI.PCX",
                "pcx/CGA_TST1.PCX",
                "pcx/no-palette-monochrome.pcx",
                "pcx/MARBLES.PCX"
        };

        for (String resource : resources) {
            PCXImageReader reader = newReaderForResource(resource);

            int width = reader.getWidth(0);
            int height = reader.getHeight(0);
            int bands = reader.getRawImageType(0).getNumBands();

            BufferedImage image = reader.read(0, null);

            assertNotNull(image, resource);
            assertEquals(width, image.getWidth(), resource);
            assertEquals(height, image.getHeight(), resource);
            assertEquals(bands, image.getRaster().getNumBands(), resource);

            if (image.getColorModel() instanceof IndexColorModel) {
                int mapSize = ((IndexColorModel) image.getColorModel()).getMapSize();
                for (int value : samples(image)) {
                    assertTrue(value >= 0 && value < mapSize, resource + " has index " + value + " outside palette of size " + mapSize);
                }
            }
        }
    }

