    @Test
    public void testReadRunLengthEncodedImage() throws IOException {
        int width = 64;
        int height = 64;

        // Each scan line is encoded as a run of 63 pixels followed by a run of 1 pixel,
        // both with the value of the scan line index.
        byte[] data = new byte[4 * height];
        for (int y = 0; y < height; y++) {
            data[y * 4] = (byte) 0xFF;     // run of 63
            data[y * 4 + 1] = (byte) y;
            data[y * 4 + 2] = (byte) 0xC1; // run of 1
            data[y * 4 + 3] = (byte) y;
        }

        PCXImageReader reader = newReader(createPCX(PCX.VERSION_3, PCX.COMPRESSION_RLE, 8, 1, width, height, width, defaultEGAPalette(), data));

        BufferedImage image = reader.read(0, null);

        assertEquals(width, image.getWidth());
        assertEquals(height, image.getHeight());

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                assertEquals(y, image.getRaster().getSample(x, y, 0), "Pixel (" + x + ", " + y + ")");
            }
        }
    }

    @Test
    public void testReadUsesTrailingVGAPalette() throws IOException {
        int width = 4;
        int height = 2;
        byte[] data = new byte[]{
                0, 5, (byte) 200, 0,
                0, 7, 0, 0
        };

        byte[] palette = new byte[1 + 256 * 3];
        palette[0] = PCX.VGA_PALETTE_MAGIC;
        for (int i = 0; i < 256; i++) {
            palette[1 + i * 3] = (byte) i;
            palette[2 + i * 3] = (byte) (255 - i);
            palette[3 + i * 3] = (byte) (i / 2);
        }

        byte[] pcx = createPCX(PCX.VERSION_3, PCX.COMPRESSION_NONE, 8, 1, width, height, width, defaultEGAPalette(), data);
        byte[] withPalette = Arrays.copyOf(pcx, pcx.length + palette.length);
        System.arraycopy(palette, 0, withPalette, pcx.length, palette.length);

        PCXImageReader reader = newReader(withPalette);

        IndexColorModel colorModel = assertInstanceOf(IndexColorModel.class, reader.getRawImageType(0).getColorModel());
        assertEquals(256, colorModel.getMapSize());

        BufferedImage image = reader.read(0, null);

        assertEquals(BufferedImage.TYPE_BYTE_INDEXED, image.getType());
        assertEquals(vgaColor(0), image.getRGB(0, 0));
        assertEquals(vgaColor(5), image.getRGB(1, 0));
        assertEquals(vgaColor(200), image.getRGB(2, 0));
        assertEquals(vgaColor(0), image.getRGB(3, 0));
        assertEquals(vgaColor(7), image.getRGB(1, 1));
    }

