    @Test
    public void testReadFiresProgressEvents() throws Exception {
        PCXImageReader reader = newReaderForResource("pcx/input.pcx");
        int height = reader.getHeight(0);
        RecordingProgressListener listener = new RecordingProgressListener();
        reader.addIIOReadProgressListener(listener);

        BufferedImage image = reader.read(0, null);

        assertNotNull(image);
        assertEquals("imageStarted", listener.events.get(0));
        assertEquals("imageComplete", listener.events.get(listener.events.size() - 1));
        assertEquals(height, listener.progress.size(), "One progress event per scan line");
        for (float progress : listener.progress) {
            assertTrue(progress >= 0f && progress <= 100f, "Unexpected progress: " + progress);
        }
        assertFalse(listener.events.contains("imageAborted"));
    }

    @Test
    public void testReadStopsAfterFirstRowWhenAborted() throws Exception {
        PCXImageReader reader = newReaderForResource("pcx/input.pcx");
        int width = reader.getWidth(0);
        int height = reader.getHeight(0);
        RecordingProgressListener listener = new RecordingProgressListener();
        reader.addIIOReadProgressListener(listener);

        reader.abort();

        BufferedImage image = reader.read(0, null);

        assertEquals(width, image.getWidth());
        assertEquals(height, image.getHeight());
        assertEquals(1, listener.progress.size(), "Reading should stop after the first scan line");
        assertTrue(listener.events.contains("imageAborted"), listener.events.toString());
        assertTrue(listener.events.indexOf("imageAborted") < listener.events.indexOf("imageComplete"), listener.events.toString());
    }

