package com.twelvemonkeys.imageio.plugins.tiff;

import com.twelvemonkeys.lang.Validate;

import java.awt.*;
import java.awt.color.*;
import java.awt.image.*;
import java.util.Objects;

import static com.twelvemonkeys.imageio.plugins.tiff.TIFFImageReader.createOffsets;
import static java.awt.image.DataBuffer.*;

/**
 * ExtraSamplesColorModel.
 *
 * @author <a href="mailto:harald.kuhr@gmail.com">Harald Kuhr</a>
 * @author last modified by $Author: harald.kuhr$
 * @version $Id: ExtraSamplesColorModel.java,v 1.0 19/11/2017 harald.kuhr Exp$
 */
final class ExtraSamplesColorModel extends ComponentColorModel {
    // NOTE: This field shadows the package protected field in the super class.
    // This is just enough to get us past a few tricky situations, but the super class
    // still thinks it has numComponents == cs.getNumComponents() + 1 for most operations
    private final int numComponents;

    private final int componentSize;

    ExtraSamplesColorModel(ColorSpace cs, boolean hasAlpha, boolean isAlphaPremultiplied, int dataType, int extraComponents) {
        this(cs, null, hasAlpha, isAlphaPremultiplied, dataType, extraComponents);
    }

    ExtraSamplesColorModel(ColorSpace cs, int[] bits, boolean hasAlpha, boolean isAlphaPremultiplied, int dataType, int extraComponents) {
        super(cs, bits, hasAlpha, isAlphaPremultiplied, Transparency.TRANSLUCENT, dataType);
        Validate.isTrue(extraComponents > 0, "Extra components must be > 0");
        this.numComponents = cs.getNumComponents() + (hasAlpha ? 1 : 0) + extraComponents;

        if (bits != null) {
            Validate.isTrue(bits.length == numComponents, "bits.length must be == " + numComponents);
            this.componentSize = bits[0];
            for (int bit : bits) {
                Validate.isTrue(bit == componentSize, "Variable bits per component not supported");
            }
        }
        else {
            this.componentSize = getDataTypeSize(dataType);
        }
    }

    @Override
    public int getNumComponents() {
        return numComponents;
    }

    @Override
    public int getComponentSize(int componentIdx) {
        return componentSize;
    }

    @Override
    public boolean isCompatibleSampleModel(SampleModel sm) {
        if (!(sm instanceof ComponentSampleModel)) {
            return false;
        }

        // Must have the same number of components
        return numComponents == sm.getNumBands() && transferType == sm.getTransferType();
    }

    @Override
    public WritableRaster getAlphaRaster(WritableRaster raster) {
        if (!hasAlpha()) {
            return null;
        }

        int x = raster.getMinX();
        int y = raster.getMinY();
        int[] band = new int[] {getAlphaComponent()};

        return raster.createWritableChild(x, y, raster.getWidth(), raster.getHeight(), x, y, band);
    }

    private int getAlphaComponent() {
        return super.getNumComponents() - 1;
    }

    @Override
    public Object getDataElements(final int rgb, final Object pixel) {
        return super.getDataElements(rgb, pixel == null ? createDataArray() : pixel);
    }

    private Object createDataArray() {
        switch (transferType) {
            case DataBuffer.TYPE_BYTE:
                return new byte[numComponents];
            case DataBuffer.TYPE_SHORT:
            case DataBuffer.TYPE_USHORT:
                return new short[numComponents];
            case DataBuffer.TYPE_INT:
                return new int[numComponents];
            case DataBuffer.TYPE_FLOAT:
                return new float[numComponents];
            case DataBuffer.TYPE_DOUBLE:
                return new double[numComponents];
        }

        throw new IllegalArgumentException("This method has not been implemented for transferType " + transferType);
    }

    @Override
    public boolean equals(final Object other) {
        if (this == other) {
            return true;
        }
        if (other == null || getClass() != other.getClass()) {
            return false;
        }

        ExtraSamplesColorModel that = (ExtraSamplesColorModel) other;

        if (hasAlpha() != that.hasAlpha() ||
                isAlphaPremultiplied() != that.isAlphaPremultiplied() ||
                getPixelSize() != that.getPixelSize() ||
                getTransparency() != that.getTransparency() ||
                numComponents != that.numComponents) {
            return false;
        }

        int[] nBits = getComponentSize();
        int[] nb = that.getComponentSize();

        if ((nBits == null) || (nb == null)) {
            return ((nBits == null) && (nb == null));
        }

        for (int i = 0; i < nBits.length; i++) {
            if (nBits[i] != nb[i]) {
                return false;
            }
        }

        return true;
    }

    @Override
    public int hashCode() {
        return Objects.hash(super.hashCode(), numComponents, componentSize);
    }

    @Override
    public SampleModel createCompatibleSampleModel(int w, int h) {
        return new PixelInterleavedSampleModel(transferType, 1, 1, numComponents, numComponents, createOffsets(numComponents));
    }

    @Override
    public WritableRaster createCompatibleWritableRaster(int w, int h) {
        switch (transferType) {
            case DataBuffer.TYPE_BYTE:
            case DataBuffer.TYPE_USHORT:
                return Raster.createInterleavedRaster(transferType, w, h, numComponents, null);
            default:
                SampleModel sampleModel = createCompatibleSampleModel(w, h);
                return Raster.createWritableRaster(sampleModel, sampleModel.createDataBuffer(), null);
        }
    }
}

/**
 * TIFFImageReaderSpi
 *
 * @author <a href="mailto:harald.kuhr@gmail.com">Harald Kuhr</a>
 * @author last modified by $Author: haraldk$
 * @version $Id: TIFFImageReaderSpi.java,v 1.0 08.05.12 15:14 haraldk Exp$
 */
public final class TIFFImageReaderSpi extends ImageReaderSpiBase {
    /**
     * Creates a {@code TIFFImageReaderSpi}.
     */
    @SuppressWarnings("WeakerAccess")
    public TIFFImageReaderSpi() {
        super(new TIFFProviderInfo());
    }

    @SuppressWarnings("unchecked")
    @Override
    public void onRegistration(final ServiceRegistry registry, final Class<?> category) {
        // Make sure we're ordered before the new JEP 262 JRE bundled TIFF plugin
        // or the Apple-provided TIFF plugin on OS X (which both happen to have the same class name)...
        ImageReaderSpi sunSpi = lookupProviderByName(registry, "com.sun.imageio.plugins.tiff.TIFFImageReaderSpi", ImageReaderSpi.class);

        if (sunSpi != null && sunSpi.getVendorName() != null
                && (sunSpi.getVendorName().startsWith("Apple") || sunSpi.getVendorName().startsWith("Oracle"))) {
            registry.setOrdering((Class<ImageReaderSpi>) category, this, sunSpi);
        }
    }

    public boolean canDecodeInput(final Object pSource) throws IOException {
        return canDecodeAs(pSource, TIFF.TIFF_MAGIC);
    }

    static boolean canDecodeAs(final Object pSource, final int versionMagic) throws IOException {
        if (!(pSource instanceof ImageInputStream)) {
            return false;
        }

        ImageInputStream stream = (ImageInputStream) pSource;

        stream.mark();
        try {
            byte[] magic = new byte[4];
            stream.readFully(magic);

            return magic[0] == 'I' && magic[1] == 'I' && magic[2] == (versionMagic & 0xFF) && magic[3] == (versionMagic >>> 8)
                    || magic[0] == 'M' && magic[1] == 'M' && magic[2] == (versionMagic >>> 8) && magic[3] == (versionMagic & 0xFF);
        }
        catch (EOFException ignore) {
            return false;
        }
        finally {
            stream.reset();
        }
    }

    public TIFFImageReader createReaderInstance(final Object pExtension) {
        return new TIFFImageReader(this);
    }

    public String getDescription(final Locale pLocale) {
        return "Aldus/Adobe Tagged Image File Format (TIFF) image reader";
    }
}

