        assertPixels(rowPattern(22, 24, 27, 30), cmb.getSubBlock(Plane.U, 0, 0));
        assertPixels(rowPattern(22, 24, 27, 30), cmb.getSubBlock(Plane.U, 0, 1));
        assertPixels(rowPattern(10, 13, 16, 18), lmb.getSubBlock(Plane.U, 1, 0));
        assertPixels(rowPattern(10, 13, 16, 18), lmb.getSubBlock(Plane.U, 1, 1));

        // The neighbouring inner sub-block edge is flat and remains unchanged.
        assertPixels(flat(30), cmb.getSubBlock(Plane.U, 1, 0));
        assertPixels(flat(30), cmb.getSubBlock(Plane.U, 1, 1));
        assertPixels(flat(10), lmb.getSubBlock(Plane.U, 0, 0));
        assertPixels(flat(10), lmb.getSubBlock(Plane.U, 0, 1));

