        assertPixels(flat(30), cmb.getSubBlock(Plane.U, 0, 1));
        assertPixels(flat(30), cmb.getSubBlock(Plane.U, 1, 1));
        assertPixels(flat(10), tmb.getSubBlock(Plane.U, 0, 0));
        assertPixels(flat(10), tmb.getSubBlock(Plane.U, 1, 0));

        assertPlane(cmb, Plane.V, flat(CHROMA_NEUTRAL));
        assertPlane(tmb, Plane.V, flat(CHROMA_NEUTRAL));
