        assertPixels(flat(50), cmb.getSubBlock(Plane.U, 1, 0));
        assertPixels(flat(50), cmb.getSubBlock(Plane.U, 1, 1));
        assertPlane(cmb, Plane.V, flat(CHROMA_NEUTRAL));
    }

    @Test
    void interFrameLevelFortyUsesFullHevFiltering() {
        MacroBlock cmb = newMacroBlock(40);
        MacroBlock lmb = newMacroBlock(40);

        fillPlane(cmb, Plane.U, flat(50));
        fillPlane(cmb, Plane.V, flat(CHROMA_NEUTRAL));
        fillPlane(lmb, Plane.U, flat(10));
        fillPlane(lmb, Plane.V, flat(CHROMA_NEUTRAL));

        int[][] edge = rowPattern(34, 34, 33, 30);
        fillSubBlock(lmb, Plane.U, 1, 0, edge);
        fillSubBlock(lmb, Plane.U, 1, 1, edge);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 0, 1);

        // An inter frame has a higher HEV threshold, so the full seven-tap path is used.
        assertPixels(rowPattern(41, 44, 47, 50), cmb.getSubBlock(Plane.U, 0, 0));
        assertPixels(rowPattern(41, 44, 47, 50), cmb.getSubBlock(Plane.U, 0, 1));
        assertPixels(rowPattern(34, 37, 39, 39), lmb.getSubBlock(Plane.U, 1, 0));
        assertPixels(rowPattern(34, 37, 39, 39), lmb.getSubBlock(Plane.U, 1, 1));

        assertPixels(flat(50), cmb.getSubBlock(Plane.U, 1, 0));
        assertPixels(flat(50), cmb.getSubBlock(Plane.U, 1, 1));
        assertPlane(cmb, Plane.V, flat(CHROMA_NEUTRAL));
    }

    @Test
    void interFrameLevelNineteenUsesHevThresholdOne() {
        MacroBlock cmb = newMacroBlock(19);
        MacroBlock lmb = newMacroBlock(19);

        fillPlane(cmb, Plane.U, flat(50));
        fillPlane(cmb, Plane.V, flat(CHROMA_NEUTRAL));
        fillPlane(lmb, Plane.U, flat(10));
        fillPlane(lmb, Plane.V, flat(CHROMA_NEUTRAL));

        int[][] edge = rowPattern(34, 34, 32, 30);
        fillSubBlock(lmb, Plane.U, 1, 0, edge);
        fillSubBlock(lmb, Plane.U, 1, 1, edge);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 0, 1);

        // Level 19 selects hev_threshold = 1, so an edge difference of two is "high variance".
        assertPixels(rowPattern(45, 50, 50, 50), cmb.getSubBlock(Plane.U, 0, 0));
        assertPixels(rowPattern(45, 50, 50, 50), cmb.getSubBlock(Plane.U, 0, 1));
        assertPixels(rowPattern(34, 34, 32, 35), lmb.getSubBlock(Plane.U, 1, 0));
        assertPixels(rowPattern(34, 34, 32, 35), lmb.getSubBlock(Plane.U, 1, 1));
    }

    @Test
    void interFrameLevelTwentyUsesHevThresholdTwo() {
        MacroBlock cmb = newMacroBlock(20);
        MacroBlock lmb = newMacroBlock(20);

        fillPlane(cmb, Plane.U, flat(50));
        fillPlane(cmb, Plane.V, flat(CHROMA_NEUTRAL));
        fillPlane(lmb, Plane.U, flat(10));
        fillPlane(lmb, Plane.V, flat(CHROMA_NEUTRAL));

        int[][] edge = rowPattern(34, 34, 32, 30);
        fillSubBlock(lmb, Plane.U, 1, 0, edge);
        fillSubBlock(lmb, Plane.U, 1, 1, edge);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 0, 1);

        // Level 20 selects hev_threshold = 2, so an edge difference of two is not "high variance".
        assertPixels(rowPattern(41, 44, 47, 50), cmb.getSubBlock(Plane.U, 0, 0));
        assertPixels(rowPattern(41, 44, 47, 50), cmb.getSubBlock(Plane.U, 0, 1));
        assertPixels(rowPattern(34, 37, 38, 39), lmb.getSubBlock(Plane.U, 1, 0));
        assertPixels(rowPattern(34, 37, 38, 39), lmb.getSubBlock(Plane.U, 1, 1));
    }

    @Test
    void sharpnessFourAllowsInteriorDifferenceAtLimit() {
        MacroBlock cmb = newMacroBlock(40);
        MacroBlock lmb = newMacroBlock(40);

        fillPlane(cmb, Plane.U, flat(50));
        fillPlane(cmb, Plane.V, flat(CHROMA_NEUTRAL));
        fillPlane(lmb, Plane.U, flat(10));
        fillPlane(lmb, Plane.V, flat(CHROMA_NEUTRAL));

        int[][] edge = rowPattern(39, 34, 33, 30);
        fillSubBlock(lmb, Plane.U, 1, 0, edge);
        fillSubBlock(lmb, Plane.U, 1, 1, edge);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 4, 0);

        // sharpness 4 halves the initial level and caps the interior limit at 9 - 4 = 5.
        // The interior difference of five is accepted at the cap, so filtering happens.
        assertPixels(rowPattern(45, 50, 50, 50), cmb.getSubBlock(Plane.U, 0, 0));
        assertPixels(rowPattern(45, 50, 50, 50), cmb.getSubBlock(Plane.U, 0, 1));
        assertPixels(rowPattern(39, 34, 33, 35), lmb.getSubBlock(Plane.U, 1, 0));
        assertPixels(rowPattern(39, 34, 33, 35), lmb.getSubBlock(Plane.U, 1, 1));
    }

    @Test
    void sharpnessFiveRejectsInteriorDifferenceAboveLimit() {
        MacroBlock cmb = newMacroBlock(40);
        MacroBlock lmb = newMacroBlock(40);

        fillPlane(cmb, Plane.U, flat(50));
        fillPlane(cmb, Plane.V, flat(CHROMA_NEUTRAL));
        fillPlane(lmb, Plane.U, flat(10));
        fillPlane(lmb, Plane.V, flat(CHROMA_NEUTRAL));

        int[][] edge = rowPattern(39, 34, 33, 30);
        fillSubBlock(lmb, Plane.U, 1, 0, edge);
        fillSubBlock(lmb, Plane.U, 1, 1, edge);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 5, 0);

        // sharpness 5 shifts by two and caps the interior limit at 9 - 5 = 4.
        // The interior difference of five now disables filtering entirely.
        assertPixels(flat(50), cmb.getSubBlock(Plane.U, 0, 0));
        assertPixels(flat(50), cmb.getSubBlock(Plane.U, 0, 1));
        assertPixels(edge, lmb.getSubBlock(Plane.U, 1, 0));
        assertPixels(edge, lmb.getSubBlock(Plane.U, 1, 1));
    }

    @Test
    void skippedInnerLoopFilterLeavesInnerEdgesUntouched() throws Exception {
        MacroBlock cmb = newMacroBlock(20);

        fillPlane(cmb, Plane.U, flat(30));
        fillSubBlock(cmb, Plane.U, 0, 0, flat(10));
        fillSubBlock(cmb, Plane.U, 0, 1, flat(10));
        fillPlane(cmb, Plane.V, flat(CHROMA_NEUTRAL));

        Field skip = MacroBlock.class.getDeclaredField("skipInnerLoopFilter");
        skip.setAccessible(true);
        skip.setBoolean(cmb, true);

        LoopFilter.loopFilterUVBlock(cmb, null, null, 0, 1);

        assertPixels(flat(10), cmb.getSubBlock(Plane.U, 0, 0));
        assertPixels(flat(10), cmb.getSubBlock(Plane.U, 0, 1));
        assertPixels(flat(30), cmb.getSubBlock(Plane.U, 1, 0));
        assertPixels(flat(30), cmb.getSubBlock(Plane.U, 1, 1));
        assertPlane(cmb, Plane.V, flat(CHROMA_NEUTRAL));
    }

    @Test
    void nullCurrentMacroBlockThrowsNullPointerException() {
        assertThrows(NullPointerException.class,
                () -> LoopFilter.loopFilterUVBlock(null, null, null, 0, 0));
    }

    private static MacroBlock newMacroBlock(int filterLevel) {
        MacroBlock macroBlock = new MacroBlock(0, 0, false);
        macroBlock.setFilterLevel(filterLevel);
        return macroBlock;
    }

    private static void fillPlane(MacroBlock macroBlock, Plane plane, int[][] pattern) {
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                fillSubBlock(macroBlock, plane, i, j, pattern);
            }
        }
    }

    private static void fillSubBlock(MacroBlock macroBlock, Plane plane, int i, int j, int[][] pattern) {
        int[][] copy = new int[4][4];
        for (int x = 0; x < 4; x++) {
            System.arraycopy(pattern[x], 0, copy[x], 0, 4);
        }
        macroBlock.getSubBlock(plane, i, j).setDest(copy);
    }

    private static int[][] flat(int value) {
        int[][] dest = new int[4][4];
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                dest[x][y] = value;
            }
        }
        return dest;
    }

    /**
     * Creates a plane whose value depends only on {@code x}; every row is identical.
     */
    private static int[][] rowPattern(int x0, int x1, int x2, int x3) {
        int[] values = {x0, x1, x2, x3};
        int[][] dest = new int[4][4];
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                dest[x][y] = values[x];
            }
        }
        return dest;
    }

    /**
     * Creates a plane whose value depends only on {@code y}; every column is identical.
     */
    private static int[][] columnPattern(int y0, int y1, int y2, int y3) {
        int[] values = {y0, y1, y2, y3};
        int[][] dest = new int[4][4];
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                dest[x][y] = values[y];
            }
        }
        return dest;
    }

    private static void assertPlane(MacroBlock macroBlock, Plane plane, int[][] expected) {
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                assertPixels(expected, macroBlock.getSubBlock(plane, i, j));
            }
        }
    }

    private static void assertPixels(int[][] expected, SubBlock subBlock) {
        int[][] actual = subBlock.getDest();
        assertNotNull(actual, "sub-block destination pixels should not be null");
        for (int x = 0; x < 4; x++) {
            assertArrayEquals(expected[x], actual[x], "unexpected pixel values in column x=" + x);
        }
    }
}
