    public void predict(VP8Frame frame) {
        SubBlock sb = this;
        SubBlock aboveSb = frame.getAboveSubBlock(sb, sb.getPlane());
        SubBlock leftSb = frame.getLeftSubBlock(sb, sb.getPlane());

        int[] above = new int[4];
        int[] left = new int[4];

        above[0] = aboveSb.getReconPredict(sb.getMode(), false)[0][3];
        above[1] = aboveSb.getReconPredict(sb.getMode(), false)[1][3];
        above[2] = aboveSb.getReconPredict(sb.getMode(), false)[2][3];
        above[3] = aboveSb.getReconPredict(sb.getMode(), false)[3][3];
        left[0] = leftSb.getReconPredict(sb.getMode(), true)[3][0];
        left[1] = leftSb.getReconPredict(sb.getMode(), true)[3][1];
        left[2] = leftSb.getReconPredict(sb.getMode(), true)[3][2];
        left[3] = leftSb.getReconPredict(sb.getMode(), true)[3][3];
        SubBlock AL = frame.getLeftSubBlock(aboveSb, sb.getPlane());

        // for above left if left and above is null use left (129?) else use
        // above (127?)
        int al;
        if (!leftSb.hasRecon() && !aboveSb.hasRecon()) {

            al = AL.getReconPredict(sb.getMode(), false)[3][3];
        }
        else if (!aboveSb.hasRecon()) {

            al = AL.getReconPredict(sb.getMode(), false)[3][3];
        }
        else {
            al = AL.getReconPredict(sb.getMode(), true)[3][3];
        }
        SubBlock AR = frame.getAboveRightSubBlock(sb, sb.plane);
        int[] ar = new int[4];
        ar[0] = AR.getReconPredict(sb.getMode(), false)[0][3];
        ar[1] = AR.getReconPredict(sb.getMode(), false)[1][3];
        ar[2] = AR.getReconPredict(sb.getMode(), false)[2][3];
        ar[3] = AR.getReconPredict(sb.getMode(), false)[3][3];
        int[][] p = new int[4][4];
        int[] pp;
        switch (sb.getMode()) {
            case Globals.B_DC_PRED:
                // System.out.println("B_DC_PRED");
                int expected_dc = 0;

                for (int i = 0; i < 4; i++) {
                    expected_dc += above[i];
                    expected_dc += left[i];
                }
                expected_dc = (expected_dc + 4) >> 3;

                for (int y = 0; y < 4; y++) {
                    for (int x = 0; x < 4; x++) {
                        p[x][y] = expected_dc;
                    }
                }

                break;
            case Globals.B_TM_PRED:

                // System.out.println("B_TM_PRED");

                // prediction similar to true_motion prediction

                for (int r = 0; r < 4; r++) {
                    for (int c = 0; c < 4; c++) {

                        int pred = above[c] - al + left[r];
                        if (pred < 0) {
                            pred = 0;
                        }

                        if (pred > 255) {
                            pred = 255;
                        }

                        p[c][r] = pred;
                    }
                }
                break;
            case Globals.B_VE_PRED:
                // System.out.println("B_VE_PRED");

                int[] ap = new int[4];
                ap[0] = (al + 2 * above[0] + above[1] + 2) >> 2;
                ap[1] = (above[0] + 2 * above[1] + above[2] + 2) >> 2;
                ap[2] = (above[1] + 2 * above[2] + above[3] + 2) >> 2;
                ap[3] = (above[2] + 2 * above[3] + ar[0] + 2) >> 2;

                for (int r = 0; r < 4; r++) {
                    for (int c = 0; c < 4; c++) {

                        p[c][r] = ap[c];
                    }
                }
                break;
            case Globals.B_HE_PRED:
                // System.out.println("B_HE_PRED");

                int[] lp = new int[4];
                lp[0] = (al + 2 * left[0] + left[1] + 2) >> 2;
                lp[1] = (left[0] + 2 * left[1] + left[2] + 2) >> 2;
                lp[2] = (left[1] + 2 * left[2] + left[3] + 2) >> 2;
                lp[3] = (left[2] + 2 * left[3] + left[3] + 2) >> 2;

                for (int r = 0; r < 4; r++) {
                    for (int c = 0; c < 4; c++) {
                        p[c][r] = lp[r];
                    }
                }
                break;
            case Globals.B_LD_PRED:
                // System.out.println("B_LD_PRED");
                p[0][0] = (above[0] + above[1] * 2 + above[2] + 2) >> 2;
                p[1][0] = p[0][1] = (above[1] + above[2] * 2 + above[3] + 2) >> 2;
                p[2][0] = p[1][1] = p[0][2] = (above[2] + above[3] * 2 + ar[0] + 2) >> 2;
                p[3][0] = p[2][1] = p[1][2] = p[0][3] = (above[3] + ar[0] * 2
                        + ar[1] + 2) >> 2;
                p[3][1] = p[2][2] = p[1][3] = (ar[0] + ar[1] * 2 + ar[2] + 2) >> 2;
                p[3][2] = p[2][3] = (ar[1] + ar[2] * 2 + ar[3] + 2) >> 2;
                p[3][3] = (ar[2] + ar[3] * 2 + ar[3] + 2) >> 2;

                break;
            case Globals.B_RD_PRED:
                // System.out.println("B_RD_PRED");
                pp = new int[9];

                pp[0] = left[3];
                pp[1] = left[2];
                pp[2] = left[1];
                pp[3] = left[0];
                pp[4] = al;
                pp[5] = above[0];
                pp[6] = above[1];
                pp[7] = above[2];
                pp[8] = above[3];

                p[0][3] = (pp[0] + pp[1] * 2 + pp[2] + 2) >> 2;
                p[1][3] = p[0][2] = (pp[1] + pp[2] * 2 + pp[3] + 2) >> 2;
                p[2][3] = p[1][2] = p[0][1] = (pp[2] + pp[3] * 2 + pp[4] + 2) >> 2;
                p[3][3] = p[2][2] = p[1][1] = p[0][0] = (pp[3] + pp[4] * 2 + pp[5] + 2) >> 2;
                p[3][2] = p[2][1] = p[1][0] = (pp[4] + pp[5] * 2 + pp[6] + 2) >> 2;
                p[3][1] = p[2][0] = (pp[5] + pp[6] * 2 + pp[7] + 2) >> 2;
                p[3][0] = (pp[6] + pp[7] * 2 + pp[8] + 2) >> 2;
                break;

