private static VP8Frame frameWithNeighbours(MacroBlock target, MacroBlock above, MacroBlock left, MacroBlock aboveLeft) throws Exception {
    int tx = target.getX();
    int ty = target.getY();
    VP8Frame frame = newFrame();
    int size = Math.max(tx + 2, 2);
    MacroBlock filler = new MacroBlock(1, 1, false);
    MacroBlock[] current = new MacroBlock[size];
    MacroBlock[] previous = new MacroBlock[size];
    MacroBlock[] top = new MacroBlock[size];
    Arrays.fill(current, filler);
    Arrays.fill(previous, filler);
    Arrays.fill(top, filler);
    if (left != null) current[tx] = left; // index tx (mbCol+1 with mbCol=tx-1)
    if (above != null) previous[tx + 1] = above;
    if (aboveLeft != null) previous[tx] = aboveLeft;
    setField(frame,"currentMacroBlockRowIndex", ty);
    setField(frame,"currentMacroBlockRow", current);
    setField(frame,"previousMacroBlockRow", previous);
    setField(frame,"topMacroBlockRow", top);
    setField(frame,"macroBlockRows", ty + 10);
    setField(frame,"macroBlockCols", tx + 10);
    return frame;
}
