package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import javax.imageio.stream.MemoryCacheImageInputStream;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.lang.reflect.Field;
import java.util.Arrays;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link MacroBlock#predictUV(VP8Frame)}.
 * <p>
 * The {@link VP8Frame} lookup of neighbouring macro blocks is arranged through
 * reflection, so that the prediction method can be driven deterministically
 * without decoding an actual WebP bitstream.
 */
class MacroBlockPredictUVTests {

    // --- DC_PRED -----------------------------------------------------------

    @Test
    void dcPredictionAtTopLeftCornerUsesNeutralValue() throws Exception {
        MacroBlock target = new MacroBlock(1, 1, true); // x = 0, y = 0
        target.setUvMode(Globals.DC_PRED);

        VP8Frame frame = frameWithNeighbours(target, null, null, null);

        target.predictUV(frame);

        assertAllSubBlocksConstant(target, 128, "U/V at top-left corner should be neutral 128");
    }

    @Test
    void dcPredictionWithOnlyAboveAveragesTopRow() throws Exception {
        MacroBlock target = new MacroBlock(1, 2, true); // x = 0, y = 1
        target.setUvMode(Globals.DC_PRED);

        MacroBlock above = new MacroBlock(1, 1, true);
        setRecon(above.getUSubBlock(0, 1), constantMatrix(10));
        setRecon(above.getUSubBlock(1, 1), constantMatrix(20));
        setRecon(above.getVSubBlock(0, 1), constantMatrix(30));
        setRecon(above.getVSubBlock(1, 1), constantMatrix(40));

        VP8Frame frame = frameWithNeighbours(target, above, null, null);

        target.predictUV(frame);

        // U: (4*10 + 4*20 + 4) >> 3 = 15
        // V: (4*30 + 4*40 + 4) >> 3 = 35
        assertAllSubBlocks(target, 15, 35, "DC average should only use the above row");
    }

    @Test
    void dcPredictionWithOnlyLeftAveragesLeftColumn() throws Exception {
        MacroBlock target = new MacroBlock(2, 1, true); // x = 1, y = 0
        target.setUvMode(Globals.DC_PRED);

        MacroBlock left = new MacroBlock(1, 1, true);
        setRecon(left.getUSubBlock(1, 0), constantMatrix(40));
        setRecon(left.getUSubBlock(1, 1), constantMatrix(60));
        setRecon(left.getVSubBlock(1, 0), constantMatrix(80));
        setRecon(left.getVSubBlock(1, 1), constantMatrix(100));

        VP8Frame frame = frameWithNeighbours(target, null, left, null);

        target.predictUV(frame);

        // U: (4*40 + 4*60 + 4) >> 3 = 50
        // V: (4*80 + 4*100 + 4) >> 3 = 90
        assertAllSubBlocks(target, 50, 90, "DC average should only use the left column");
    }

    @Test
    void dcPredictionWithAboveAndLeftRoundsHalfUp() throws Exception {
        MacroBlock target = new MacroBlock(2, 2, true); // x = 1, y = 1
        target.setUvMode(Globals.DC_PRED);

        MacroBlock above = new MacroBlock(1, 1, true);
        setRecon(above.getUSubBlock(0, 1), constantMatrix(10));
        setRecon(above.getUSubBlock(1, 1), constantMatrix(20));
        setRecon(above.getVSubBlock(0, 1), constantMatrix(30));
        setRecon(above.getVSubBlock(1, 1), constantMatrix(40));

        MacroBlock left = new MacroBlock(1, 1, true);
        setRecon(left.getUSubBlock(1, 0), constantMatrix(40));
        setRecon(left.getUSubBlock(1, 1), constantMatrix(60));
        setRecon(left.getVSubBlock(1, 0), constantMatrix(80));
        setRecon(left.getVSubBlock(1, 1), constantMatrix(100));

        VP8Frame frame = frameWithNeighbours(target, above, left, null);

        target.predictUV(frame);

        // U: (120 + 400 + 8) >> 4 = 33, i.e. 32.5 rounded up
        // V: (280 + 720 + 8) >> 4 = 63, i.e. 62.5 rounded up
        assertAllSubBlocks(target, 33, 63, "DC average should use above and left and round half up");
    }

    // --- V_PRED ------------------------------------------------------------

    @Test
