class MacroBlockPredictUVTests {

    // --- DC_PRED -----------------------------------------------------------

    @Test
    void dcPredictionAtTopLeftCornerUsesNeutralValue() throws Exception {
        MacroBlock target = new MacroBlock(1, 1, true); // x = 0, y = 0
        target.setUvMode(Globals.DC_PRED);

        VP8Frame frame = frameWithNeighbours(target, null, null, null);

        target.predictUV(frame);

        assertAllSubBlocksConstant(target, 128, "U/V at top-left corner should be neutral 128");
    }

    @Test
    void dcPredictionWithOnlyAboveAveragesTopRow() throws Exception {
        MacroBlock target = new MacroBlock(1, 2, true); // x = 0, y = 1
        target.setUvMode(Globals.DC_PRED);

        MacroBlock above = new MacroBlock(1, 1, true);
        setRecon(above.getUSubBlock(0, 1), constantMatrix(10));
        setRecon(above.getUSubBlock(1, 1), constantMatrix(20));
        setRecon(above.getVSubBlock(0, 1), constantMatrix(30));
        setRecon(above.getVSubBlock(1, 1), constantMatrix(40));

        VP8Frame frame = frameWithNeighbours(target, above, null, null);

        target.predictUV(frame);

        // U: (4*10 + 4*20 + 4) >> 3 = 15
        // V: (4*30 + 4*40 + 4) >> 3 = 35
        assertAllSubBlocks(target, 15, 35, "DC average should only use the above row");
    }

