    @Test
    void tmPredictionUsesTopLeftSampleAndClampsToByteRange() throws Exception {
        VP8Frame frame = newFrame();
        MacroBlock macroBlock = macroBlockAt(1, 1);
        MacroBlock above = newMacroBlock();
        MacroBlock left = newMacroBlock();
        MacroBlock aboveLeft = newMacroBlock();

        int[][] aboveLastColumns = {
                {0, 0, 0, 0},
                {50, 60, 70, 80},
                {100, 110, 120, 130},
                {200, 220, 240, 255}
        };
        for (int column = 0; column < 4; column++) {
            setLastColumn(above.getYSubBlock(column, 3), aboveLastColumns[column]);
        }

        int[][] leftBottomRows = {
                {0, 0, 0, 0},
                {50, 60, 70, 80},
                {100, 110, 120, 130},
                {200, 220, 240, 255}
        };
        for (int row = 0; row < 4; row++) {
            setBottomRow(left.getYSubBlock(3, row), leftBottomRows[row]);
        }

        int[][] aboveLeftSamples = new int[4][4];
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                aboveLeftSamples[x][y] = 100;
            }
        }
