            if (i > 0) {
                above = uSubBlocks[j][i - 1];
            }
            uSubBlocks[j][i] = new SubBlock(this, above, left,
                    SubBlock.Plane.U);
        }
    }

    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            left = null;
            above = null;
            if (j > 0) {
                left = vSubBlocks[j - 1][i];
            }
            if (i > 0) {
                above = vSubBlocks[j][i - 1];
